(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("horace-odes-b", [{"sp": "HDR", "t": "Carmina et Carmen Saeculare"}, {"sp": "HDR", "t": "Liber I", "st": "1"}, {"sp": "SEC", "t": "Carmen I", "st": "1.1"}, {"sp": "N", "t": "Maecenas atavis edite regibus,<br>o et praesidium et dulce decus meum:<br>sunt quos curriculo pulverem Olympicum<br>collegisse iuvat metaque fervidis<br>evitata rotis palmaque nobilis<br>terrarum dominos evehit ad deos;<br>hunc, si mobilium turba Quiritium<br>certat tergeminis tollere honoribus,<br>illum, si proprio condidit horreo<br>quidquid de Libycis verritur areis.<br>gaudentem patrios findere sarculo<br>agros Attalicis condicionibus<br>numquam demoveas, ut trabe Cypria<br>Myrtoum pavidus nauta secet mare.<br>luctantem Icariis fluctibus Africum<br>mercator metuens otium et oppidi<br>laudat rura sui; mox reficit rates<br>quassas indocilis pauperiem pati.<br>est qui nec veteris pocula Massici<br>nec partem solido demere de die<br>spernit, nunc viridi membra sub arbuto<br>stratus, nunc ad aquae lene caput sacrae.<br>multos castra iuvant et lituo tubae<br>permixtus sonitus bellaque matribus<br>detestata. manet sub Iove frigido<br>venator tenerae coniugis inmemor,<br>seu visa est catulis cerva fidelibus<br>seu rupit teretes Marsus aper plagas.<br>me doctarum hederae praemia frontium<br>dis miscent superis, me gelidum nemus<br>Nympharumque leves cum Satyris chori<br>secernunt populo, si neque tibias<br>Euterpe cohibet nec Polyhymnia<br>Lesboum refugit tendere barbiton.<br>quodsi me lyricis vatibus inseres,<br>sublimi feriam sidera vertice.", "st": "1.1"}, {"sp": "SEC", "t": "Carmen II", "st": "1.2"}, {"sp": "N", "t": "Iam satis terris nivis atque dirae<br>grandinis misit pater et rubente<br>dextera sacras iaculatus arcis<br>terruit urbem,<br><br>terruit gentis, grave ne rediret<br>saeculum Pyrrhae nova monstra questae,<br>omne cum Proteus pecus egit altos<br>visere montis,<br><br>piscium et summa genus haesit ulmo,<br>nota quae sedes fuerat columbis,<br>et superiecto pavidae natarunt<br>aequore dammae.<br><br>vidimus flavum Tiberim retortis<br>litore Etrusco violenter undis<br>ire deiectum monumenta regis<br>templaque Vestae,<br><br>Iliae dum se nimium querenti<br>iactat ultorem, vagus et sinistra<br>labitur ripa Iove non probante u-<br>xorius amnis.<br><br>audiet civis acuisse ferrum,<br>quo graves Persae melius perirent,<br>audiet pugnas vitio parentum<br>rara iuventus.<br><br>quem vocet divum populus ruentis<br>imperi rebus? prece qua fatigent<br>virgines sanctae minus audientem<br>carmina Vestam?<br><br>cui dabit partis scelus expiandi<br>Iuppiter? tandem venias precamur<br>nube candentis umeros amictus<br>augur Apollo;<br><br>sive tu mavis, Erycina ridens,<br>quam Iocus circum volat et Cupido;<br>sive neglectum genus et nepotes<br>respicis, auctor<br><br>heu nimis longo satiate ludo,<br>quem iuvat clamor galeaeque leves<br>acer et Marsi peditis cruentum<br>voltus in hostem;<br><br>sive mutata iuvenem figura<br>ales in terris imitaris almae<br>filius Maiae, patiens vocari<br>Caesaris ultor:<br><br>serus in caelum redeas diuque<br>laetus intersis populo Quirini<br>neve te nostris vitiis iniquum<br>ocior aura<br><br>tollat; hic magnos potius triumphos,<br>hic ames dici pater atque princeps<br>neu sinas Medos equitare inultos<br>te duce, Caesar.", "st": "1.2"}, {"sp": "SEC", "t": "Carmen III", "st": "1.3"}, {"sp": "N", "t": "Sic te diva potens Cypri,<br>sic fratres Helenae, lucida sidera,<br>ventorumque regat pater<br>obstrictis aliis praeter Iapyga,<br>navis, quae tibi creditum<br>debes Vergilium; finibus Atticis<br>reddas incolumem precor<br>et serves animae dimidium meae.<br>illi robur et aes triplex<br>circa pectus erat, qui fragilem truci<br>conmisit pelago ratem<br>primus: nec timuit praecipitem Africum<br>decertantem Aquilonibus<br>nec tristis Hyadas nec rabiem Noti,<br>quo non arbiter Hadriae<br>maior, tollere seu ponere volt freta;<br>quem mortis timuit gradum<br>qui siccis oculis monstra natantia,<br>qui vidit mare turbidum et<br>infamis scopulos Acroceraunia?<br>nequiquam deus abscidit<br>prudens oceano dissociabili<br>terras, si tamen inpiae<br>non tangenda rates transiliunt vada.<br>audax omnia perpeti<br>gens humana ruit per vetitum nefas:<br>audax Iapeti genus<br>ignem fraude mala gentibus intulit;<br>post ignem aetheria domo<br>subductum macies et nova febrium<br>terris incubuit cohors<br>semotique prius tarda necessitas<br>Leti corripuit gradum;<br>expertus vacuum Daedalus aera<br>pennis non homini datis;<br>perrupit Acheronta Herculeus labor.<br>nil mortalibus ardui est:<br>caelum ipsum petimus stultitia neque<br>per nostrum patimur scelus<br>iracunda Iovem ponere fulmina.", "st": "1.3"}, {"sp": "SEC", "t": "Carmen IV", "st": "1.4"}, {"sp": "N", "t": "Solvitur acris hiems grata vice veris et Favoni<br>trahuntque siccas machinae carinas<br>ac neque iam stabulis gaudet pecus aut arator igni<br>nec prata canis albicant pruinis.<br>iam Cytherea choros ducit Venus imminente luna<br>iunctaeque Nymphis Gratiae decentes<br>alterno terram quatiunt pede, dum gravis Cyclopum<br>Volcanus ardens visit officinas.<br>nunc decet aut viridi nitidum caput impedire myrto<br>aut flore, terrae quem ferunt solutae,<br>nunc et in umbrosis Fauno decet immolare lucis,<br>seu poscat agna sive malit haedo.<br>pallida Mors aequo pulsat pede pauperum tabernas<br>regumque turris. o beate Sesti,<br>vitae summa brevis spem nos vetat inchoare longam;<br>iam te premet nox fabulaeque Manes<br>et domus exilis Plutonia; quo simul mearis,<br>nec regna vini sortiere talis<br>nec tenerum Lycidan mirabere, quo calet iuventus<br>nunc omnis et mox virgines tepebunt.", "st": "1.4"}, {"sp": "SEC", "t": "Carmen V", "st": "1.5"}, {"sp": "N", "t": "Quis multa gracilis te puer in rosa<br>perfusus liquidis urget odoribus<br>grato, Pyrrha, sub antro?<br>cui flavam religas comam<br><br>simplex munditiis? heu quotiens fidem<br>mutatosque deos flebit et aspera<br>nigris aequora ventis<br>emirabitur insolens<br><br>qui nunc te fruitur credulus aurea,<br>qui semper vacuam, semper amabilem<br>sperat, nescius aurae<br>fallacis. miseri, quibus<br><br>intemptata nites. me tabula sacer<br>votiva paries indicat uvida<br>suspendisse potenti<br>vestimenta maris deo.", "st": "1.5"}, {"sp": "SEC", "t": "Carmen VI", "st": "1.6"}, {"sp": "N", "t": "Scriberis Vario fortis et hostium<br>victor Maeonii carminis alite,<br>quam rem cumque ferox navibus aut equis<br>miles te duce gesserit.<br><br>nos, Agrippa, neque haec dicere nec gravem<br>Pelidae stomachum cedere nescii<br>nec cursus duplicis per mare Ulixei<br>nec saevam Pelopis domum<br><br>conamur, tenues grandia, dum pudor<br>inbellisque lyrae Musa potens vetat<br>laudes egregii Caesaris et tuas<br>culpa deterere ingeni.<br><br>quis Martem tunica tectum adamantina<br>digne scripserit aut pulvere Troico<br>nigrum Merionen aut ope Palladis<br>Tydiden superis parem?<br><br>nos convivia, nos proelia virginum<br>sectis in iuvenes unguibus acrium<br>cantamus, vacui sive quid urimur,<br>non praeter solitum leves.", "st": "1.6"}, {"sp": "SEC", "t": "Carmen VII", "st": "1.7"}, {"sp": "N", "t": "Laudabunt alii claram Rhodon aut Mytilenen<br>aut Epheson bimarisve Corinthi<br>moenia vel Baccho Thebas vel Apolline Delphos<br>insignis aut Thessala Tempe;<br>sunt quibus unum opus est intactae Palladis urbem<br>carmine perpetuo celebrare et<br>undique decerptam fronti praeponere olivam;<br>plurimus in Iunonis honorem<br>aptum dicet equis Argos ditisque Mycenas:<br>me nec tam patiens Lacedaemon<br>nec tam Larisae percussit campus opimae<br>quam domus Albuneae resonantis<br>et praeceps Anio ac Tiburni lucus et uda<br>mobilibus pomaria rivis.<br>albus ut obscuro deterget nubila caelo<br>saepe Notus neque parturit imbris<br>perpetuos, sic tu sapiens finire memento<br>tristitiam vitaeque labores<br>molli, Plance, mero, seu te fulgentia signis<br>castra tenent seu densa tenebit<br>Tiburis umbra tui. Teucer Salamina patremque<br>cum fugeret, tamen uda Lyaeo<br>tempora populea fertur vinxisse corona<br>sic tristis adfatus amicos:<br>“quo nos cumque feret melior fortuna parente,<br>ibimus—o socii comitesque,<br>nil desperandum Teucro duce et auspice Teucro:<br>certus enim promisit Apollo<br>ambiguam tellure nova Salamina futuram.<br>o fortes peioraque passi<br>mecum saepe viri, nunc vino pellite curas;<br>cras ingens iterabimus aequor.”", "st": "1.7"}, {"sp": "SEC", "t": "Carmen VIII", "st": "1.8"}, {"sp": "N", "t": "Lydia, dic per omnis<br>te deos oro, Sybarin cur properes amando<br>perdere, cur apricum<br>oderit campum patiens pulveris atque solis,<br>cur neque militaris<br>inter aequalis equitet, Gallica nec lupatis<br>temperet ora frenis?<br>cur timet flavum Tiberim tangere? cur olivum<br>sanguine viperino<br>cautius vitat neque iam livida gestat armis<br>bracchia saepe disco,<br>saepe trans finem iaculo nobilis expedito?<br>quid latet, ut marinae<br>filium dicunt Thetidis sub lacrimosa Troiae<br>funera, ne virilis<br>cultus in caedem et Lycias proriperet catervas?", "st": "1.8"}, {"sp": "SEC", "t": "Carmen IX", "st": "1.9"}, {"sp": "N", "t": "Vides ut alta stet nive candidum<br>Soracte nec iam sustineant onus<br>silvae laborantes geluque<br>flumina constiterint acuto?<br><br>dissolve frigus ligna super foco<br>large reponens atque benignius<br>deprome quadrimum Sabina,<br>o Thaliarche, merum diota.<br><br>permitte divis cetera, qui simul<br>stravere ventos aequore fervido<br>deproeliantis, nec cupressi<br>nec veteres agitantur orni.<br><br>quid sit futurum cras, fuge quaerere et<br>quem Fors dierum cumque dabit, lucro<br>adpone nec dulcis amores<br>sperne puer neque tu choreas,<br><br>donec virenti canities abest<br>morosa. nunc et campus et areae<br>lenesque sub noctem susurri<br>conposita repetantur hora,<br><br>nunc et latentis proditor intumo<br>gratus puellae risus ab angulo<br>pignusque dereptum lacertis<br>aut digito male pertinaci.", "st": "1.9"}, {"sp": "SEC", "t": "Carmen X", "st": "1.10"}, {"sp": "N", "t": "Mercuri facunde nepos Atlantis,<br>qui feros cultus hominum recentum<br>voce formasti catus et decorae<br>more palaestrae,<br><br>te canam, magni Iovis et deorum<br>nuntium curvaeque lyrae parentem,<br>callidum, quidquid placuit, iocoso<br>condere furto.<br><br>te, boves olim nisi reddidisses<br>per dolum amotas, puerum minaci<br>voce dum terret, viduus pharetra<br>risit Apollo.<br><br>quin et Atridas duce te superbos<br>Ilio dives Priamus relicto<br>Thessalosque ignis et iniqua Troiae<br>castra fefellit.<br><br>tu pias laetis animas reponis<br>sedibus virgaque levem coerces<br>aurea turbam, superis deorum<br>gratus et imis.", "st": "1.10"}, {"sp": "SEC", "t": "Carmen XI", "st": "1.11"}, {"sp": "N", "t": "Tu ne quaesieris, scire nefas, quem mihi, quem tibi<br>finem di dederint, Leuconoe, nec Babylonios<br>temptaris numeros. ut melius, quidquid erit, pati.<br>seu pluris hiemes seu tribuit Iuppiter ultimam,<br>quae nunc oppositis debilitat pumicibus mare<br>Tyrrhenum: sapias, vina liques et spatio brevi<br>spem longam reseces. dum loquimur, fugerit invida<br>aetas: carpe diem quam minimum credula postero.", "st": "1.11"}, {"sp": "SEC", "t": "Carmen XII", "st": "1.12"}, {"sp": "N", "t": "Quem virum aut heroa lyra vel acri<br>tibia sumis celebrare, Clio?<br>quem deum? cuius recinet iocosa<br>nomen imago<br><br>aut in umbrosis Heliconis oris<br>aut super Pindo gelidove in Haemo?<br>unde vocalem temere insecutae<br>Orphea silvae,<br><br>arte materna rapidos morantem<br>fluminum lapsus celeresque ventos,<br>blandum et auritas fidibus canoris<br>ducere quercus.<br><br>quid prius dicam solitis parentis<br>laudibus, qui res hominum ac deorum,<br>qui mare ac terras variisque mundum<br>temperat horis?<br><br>unde nil maius generatur ipso<br>nec viget quidquam simile aut secundum.<br>proximos illi tamen occupavit<br>Pallas honores<br><br>proeliis audax. neque te silebo,<br>Liber et saevis inimica virgo<br>beluis, nec te, metuende certa<br>Phoebe sagitta.<br><br>dicam et Alciden puerosque Ledae,<br>hunc equis, illum superare pugnis<br>nobilem; quorum simul alba nautis<br>stella refulsit,<br><br>defluit saxis agitatus umor,<br>concidunt venti fugiuntque nubes<br>et minax, quia sic voluere, ponto<br>unda recumbit.<br><br>Romulum post hos prius an quietum<br>Pompili regnum memorem, an superbos<br>Tarquini fascis, dubito, an Catonis<br>nobile letum:<br><br>Regulum et Scauros animaeque magnae<br>prodigum Paulum superante Poeno<br>gratus insigni referam camena<br>Fabriciumque.<br><br>hunc et incomptis Curium capillis<br>utilem bello tulit et Camillum<br>saeva paupertas et avitus apto<br>cum lare fundus.<br><br>crescit occulto velut arbor aevo<br>fama Marcelli; micat inter omnis<br>Iulium sidus velut inter ignis<br>luna minores.<br><br>gentis humanae pater atque custos,<br>orte Saturno, tibi cura magni<br>Caesaris fatis data: tu secundo<br>Caesare regnes.<br><br>ille seu Parthos Latio imminentis<br>egerit iusto domitos triumpho<br>sive subiectos Orientis orae<br>Seras et Indos,<br><br>te minor latum reget aequos orbem:<br>tu gravi curru quaties Olympum,<br>tu parum castis inimica mittes<br>fulmina lucis.", "st": "1.12"}, {"sp": "SEC", "t": "Carmen XIII", "st": "1.13"}, {"sp": "N", "t": "Cum tu, Lydia, Telephi<br>cervicem roseam, cerea Telephi<br>laudas bracchia, vae, meum<br>fervens difficili bile tumet iecur.<br>tum nec mens mihi nec color<br>certa sede manet, umor et in genas<br>furtim labitur arguens,<br>quam lentis penitus macerer ignibus.<br>uror, seu tibi candidos<br>turparunt umeros inmodicae mero<br>rixae sive puer furens<br>inpressit memorem dente labris notam.<br>non, si me satis audias,<br>speres perpetuum dulcia barbare<br>laedentem oscula, quae Venus<br>quinta parte sui nectaris imbuit.<br>felices ter et amplius<br>quos inrupta tenet copula nec malis<br>divolsus querimoniis<br>suprema citius solvet amor die.", "st": "1.13"}, {"sp": "SEC", "t": "Carmen XIV", "st": "1.14"}, {"sp": "N", "t": "O navis, referent in mare te novi<br>fluctus. o quid agis? fortiter occupa<br>portum. nonne vides, ut<br>nudum remigio latus<br><br>et malus celeri saucius Africo<br>antemnaeque gemant ac sine funibus<br>vix durare carinae<br>possint imperiosius<br><br>aequor? non tibi sunt integra lintea,<br>non di, quos iterum pressa voces malo.<br>quamvis Pontica pinus,<br>silvae filia nobilis,<br><br>iactes et genus et nomen inutile:<br>nil pictis timidus navita puppibus<br>fidit. tu, nisi ventis<br>debes ludibrium, cave.<br><br>nuper sollicitum quae mihi taedium,<br>nunc desiderium curaque non levis,<br>interfusa nitentis<br>vites aequora Cycladas.", "st": "1.14"}, {"sp": "SEC", "t": "Carmen XV", "st": "1.15"}, {"sp": "N", "t": "Pastor cum traheret per freta navibus<br>Idaeis Helenen perfidus hospitam,<br>ingrato celeres obruit otio<br>ventos ut caneret fera<br><br>Nereus fata. “mala ducis avi domum<br>quam multo repetet Graecia milite<br>coniurata tuas rumpere nuptias<br>et regnum Priami vetus.<br><br>heu heu, quantus equis, quantus adest viris<br>sudor, quanta moves funera Dardanae<br>genti. iam galeam Pallas et aegida<br>currusque et rabiem parat.<br><br>nequiquam Veneris praesidio ferox<br>pectes caesariem grataque feminis<br>inbelli cithara carmina divides;<br>nequiquam thalamo gravis<br><br>hastas et calami spicula Cnosii<br>vitabis strepitumque et celerem sequi<br>Aiacem: tamen, heu serus, adulteros<br>crines pulvere collines.<br><br>non Laertiaden, exitium tuae<br>genti, non Pylium Nestora respicis?<br>urgent inpavidi te Salaminius<br>Teucer, te Sthenelus, sciens<br><br>pugnae sive opus est imperitare equis,<br>non auriga piger. Merionen quoque<br>nosces. ecce furit, te reperire atrox,<br>Tydides melior patre:<br><br>quem tu, cervus uti vallis in altera<br>visum parte lupum graminis inmemor,<br>sublimi fugies mollis anhelitu,<br>non hoc pollicitus tuae.<br><br>iracunda diem proferet Ilio<br>matronisque Phrygum classis Achillei;<br>post certas hiemes uret Achaicus<br>ignis Iliacas domos.", "st": "1.15"}, {"sp": "SEC", "t": "Carmen XVI", "st": "1.16"}, {"sp": "N", "t": "O matre pulcra filia pulchrior,<br>quem criminosis cumque voles modum<br>pones iambis, sive flamma<br>sive mari libet Hadriano.<br><br>non Dindymene, non adytis quatit<br>mentem sacerdotum incola Pythius,<br>non Liber aeque, non acuta<br>sic geminant Corybantes aera,<br><br>tristes ut irae, quas neque Noricus<br>deterret ensis nec mare naufragum<br>nec saevos ignis nec tremendo<br>Iuppiter ipse ruens tumultu.<br><br>fertur Prometheus addere principi<br>limo coactus particulam undique<br>desectam et insani leonis<br>vim stomacho adposuisse nostro.<br><br>irae Thyesten exitio gravi<br>stravere et altis urbibus ultimae<br>stetere causae, cur perirent<br>funditus inprimeretque muris<br><br>hostile aratrum exercitus insolens.<br>conpesce mentem: me quoque pectoris<br>temptavit in dulci iuventa<br>fervor et in celeres iambos<br><br>misit furentem. nunc ego mitibus<br>mutare quaero tristia, dum mihi<br>fias recantatis amica<br>opprobriis animumque reddas.", "st": "1.16"}, {"sp": "SEC", "t": "Carmen XVII", "st": "1.17"}, {"sp": "N", "t": "Velox amoenum saepe Lucretilem<br>mutat Lycaeo Faunus et igneam<br>defendit aestatem capellis<br>usque meis pluviosque ventos.<br><br>inpune tutum per nemus arbutos<br>quaerunt latentis et thyma deviae<br>olentis uxores mariti<br>nec viridis metuunt colubras<br><br>nec Martialis haediliae lupos,<br>utcumque dulci, Tyndari, fistula<br>valles et Usticae cubantis<br>levia personuere saxa.<br><br>di me tuentur, dis pietas mea<br>et musa cordi est. hic tibi copia<br>manabit ad plenum benigno<br>ruris honorum opulenta cornu.<br><br>hic in reducta valle Caniculae<br>vitabis aestus et fide Teia<br>dices laborantis in uno<br>Penelopen vitreamque Circen;<br><br>hic innocentis pocula Lesbii<br>duces sub umbra nec Semeleius<br>cum Marte confundet Thyoneus<br>proelia nec metues protervum<br><br>suspecta Cyrum, ne male dispari<br>incontinentis iniciat manus<br>et scindat haerentem coronam<br>crinibus inmeritamque vestem.", "st": "1.17"}, {"sp": "SEC", "t": "Carmen XVIII", "st": "1.18"}, {"sp": "N", "t": "Nullam, Vare, sacra vite prius severis arborem<br>circa mite solum Tiburis et moenia Catili;<br>siccis omnia nam dura deus proposuit neque<br>mordaces aliter diffugiunt sollicitudines.<br>quis post vina gravem militiam aut pauperiem crepat?<br>quis non te potius, Bacche pater, teque, decens Venus?<br>ac ne quis modici transiliat munera Liberi,<br>Centaurea monet cum Lapithis rixa super mero<br>debellata, monet Sithoniis non levis Euhius,<br>cum fas atque nefas exiguo fine libidinum<br>discernunt avidi. non ego te, candide Bassareu,<br>invitum quatiam nec variis obsita frondibus<br>sub divum rapiam. saeva tene cum Berecyntio<br>cornu tympana, quae subsequitur caecus amor sui<br>et tollens vacuum plus nimio gloria verticem<br>arcanique fides prodiga, perlucidior vitro.", "st": "1.18"}, {"sp": "SEC", "t": "Carmen XIX", "st": "1.19"}, {"sp": "N", "t": "Mater saeva Cupidinum<br>Thebanaeque iubet me Semelae puer<br>et lasciva Licentia<br>finitis animum reddere amoribus.<br>urit me Glycerae nitor<br>splendentis Pario marmore purius,<br>urit grata protervitas<br>et voltus nimium lubricus adspici.<br>in me tota ruens Venus<br>Cyprum deseruit nec patitur Scythas<br>et versis animosum equis<br>Parthum dicere nec quae nihil attinent.<br>hic vivum mihi caespitem, hic<br>verbenas, pueri, ponite turaque<br>bimi cum patera meri:<br>mactata veniet lenior hostia.", "st": "1.19"}, {"sp": "SEC", "t": "Carmen XX", "st": "1.20"}, {"sp": "N", "t": "Vile potabis modicis Sabinum<br>cantharis, Graeca quod ego ipse testa<br>conditum levi, datus in theatro<br>cum tibi plausus,<br><br>clare Maecenas eques, ut paterni<br>fluminis ripae simul et iocosa<br>redderet laudes tibi Vaticani<br>montis imago.<br><br>Caecubum et prelo domitam Caleno<br>tu bibes uvam: mea nec Falernae<br>temperant vites neque Formiani<br>pocula colles.", "st": "1.20"}, {"sp": "SEC", "t": "Carmen XXI", "st": "1.21"}, {"sp": "N", "t": "Dianam tenerae dicite virgines,<br>intonsum pueri dicite Cynthium<br>Latonamque supremo<br>dilectam penitus Iovi.<br><br>vos laetam fluviis et nemorum coma<br>quaecumque aut gelido prominet Algido<br>nigris aut Erymanthi<br>silvis aut viridis Cragi;<br><br>vos Tempe totidem tollite laudibus<br>natalemque, mares, Delon Apollinis<br>insignemque pharetra<br>fraternaque umerum lyra.<br><br>hic bellum lacrimosum, hic miseram famem<br>pestemque a populo et principe Caesare in<br>Persas atque Britannos<br>vestra motus aget prece.", "st": "1.21"}, {"sp": "SEC", "t": "Carmen XXII", "st": "1.22"}, {"sp": "N", "t": "Integer vitae scelerisque purus<br>non eget Mauris iaculis neque arcu<br>nec venenatis gravida sagittis,<br>Fusce, pharetra,<br><br>sive per Syrtis iter aestuosas<br>sive facturus per inhospitalem<br>Caucasum vel quae loca fabulosus<br>lambit Hydaspes.<br><br>namque me silva lupus in Sabina,<br>dum meam canto Lalagen et ultra<br>terminum curis vagor expeditis,<br>fugit inermem;<br><br>quale portentum neque militaris<br>Daunias latis alit aesculetis<br>nec Iubae tellus generat, leonum<br>arida nutrix.<br><br>pone me pigris ubi nulla campis<br>arbor aestiva recreatur aura,<br>quod latus mundi nebulae malusque<br>Iuppiter urget;<br><br>pone sub curru nimium propinqui<br>solis in terra domibus negata:<br>dulce ridentem Lalagen amabo,<br>dulce loquentem.", "st": "1.22"}, {"sp": "SEC", "t": "Carmen XXIII", "st": "1.23"}, {"sp": "N", "t": "Vitas hinnuleo me similis, Chloe,<br>quaerenti pavidam montibus aviis<br>matrem non sine vano<br>aurarum et siluae metu.<br><br>nam seu mobilibus veris inhorruit<br>adventus foliis seu virides rubum<br>dimovere lacertae,<br>et corde et genibus tremit.<br><br>atqui non ego te tigris ut aspera<br>Gaetulusve leo frangere persequor:<br>tandem desine matrem<br>tempestiva sequi viro.", "st": "1.23"}, {"sp": "SEC", "t": "Carmen XXIV", "st": "1.24"}, {"sp": "N", "t": "Quis desiderio sit pudor aut modus<br>tam cari capitis? praecipe lugubris<br>cantus, Melpomene, cui liquidam pater<br>vocem cum cithara dedit.<br><br>ergo Quintilium perpetuus sopor<br>urget? cui Pudor et Iustitiae soror<br>incorrupta Fides nudaque Veritas<br>quando ullum inveniet parem?<br><br>multis ille bonis flebilis occidit,<br>nulli flebilior quam tibi, Vergili.<br>tu, frustra pius, heu non ita creditum<br>poscis Quintilium deos.<br><br>quid? si Threicio blandius Orpheo<br>auditam moderere arboribus fidem,<br>num vanae redeat sanguis imagini,<br>quam virga semel horrida<br><br>non lenis precibus fata recludere<br>nigro conpulerit Mercurius gregi?<br>durum: sed levius fit patientia<br>quidquid corrigere est nefas.", "st": "1.24"}, {"sp": "SEC", "t": "Carmen XXVI", "st": "1.26"}, {"sp": "N", "t": "Musis amicus tristitiam et metus<br>tradam protervis in mare Creticum<br>portare ventis, quis sub Arcto<br>rex gelidae metuatur orae,<br><br>quid Tiridaten terreat, unice<br>securus. o quae fontibus integris<br>gaudes, apricos necte flores,<br>necte meo Lamiae coronam,<br><br>Piplei dulcis. nil sine te mei<br>prosunt honores: hunc fidibus novis,<br>hunc Lesbio sacrare plectro<br>teque tuasque decet sorores.", "st": "1.26"}, {"sp": "SEC", "t": "Carmen XXVII", "st": "1.27"}, {"sp": "N", "t": "Natis in usum laetitiae scyphis<br>pugnare Thracum est: tollite barbarum<br>morem verecundumque Bacchum<br>sanguineis prohibete rixis.<br><br>vino et lucernis Medus acinaces<br>immane quantum discrepat: inpium<br>lenite clamorem sodales<br>et cubito remanete presso.<br><br>voltis severi me quoque sumere<br>partem Falerni? dicat Opuntiae<br>frater Megillae, quo beatus<br>volnere, qua pereat sagitta.<br><br>cessat voluntas? non alia bibam<br>mercede. quae te cumque domat Venus,<br>non erubescendis adurit<br>ignibus ingenuoque semper<br><br>amore peccas. quidquid habes, age,<br>depone tutis auribus. a miser,<br>quanta laborabas Charybdi,<br>digne puer meliore flamma.<br><br>quae saga, quis te solvere Thessalis<br>magus venenis, quis poterit deus?<br>vix inligatum te triformi<br>Pegasus expediet Chimaera.", "st": "1.27"}, {"sp": "SEC", "t": "Carmen XXVIII", "st": "1.28"}, {"sp": "N", "t": "Te maris et terrae numeroque carentis harenae<br>mensorem cohibent, Archyta,<br>pulveris exigui prope litus parva Matinum<br>munera nec quicquam tibi prodest<br>aerias temptasse domos animoque rotundum<br>percurrisse polum morituro.<br>occidit et Pelopis genitor, conviva deorum,<br>Tithonusque remotus in auras<br>et Iovis arcanis Minos admissus habentque<br>Tartara Panthoiden iterum Orco<br>demissum, quamvis clipeo Troiana refixo<br>tempora testatus nihil ultra<br>nervos atque cutem morti concesserat atrae,<br>iudice te non sordidus auctor<br>naturae verique. sed omnis una manet nox<br>et calcanda semel via leti.<br>dant alios Furiae torvo spectacula Marti,<br>exitio est avidum mare nautis;<br>mixta senum ac iuvenum densentur funera, nullum<br>saeva caput Proserpina fugit:<br>me quoque devexi rapidus comes Orionis<br>Illyricis Notus obruit undis.<br>at tu, nauta, vagae ne parce malignus harenae<br>ossibus et capiti inhumato<br>particulam dare: sic quodcumque minabitur Eurus<br>fluctibus Hesperiis Venusinae<br>plectantur silvae te sospite multaque merces<br>unde potest tibi defluat aequo<br>ab Iove Neptunoque sacri custode Tarenti.<br>neglegis inmeritis nocituram<br>postmodo te natis fraudem conmittere? fors et<br>debita iura vicesque superbae<br>te maneant ipsum: precibus non linquar inultis<br>teque piacula nulla resolvent.<br>quamquam festinas, non est mora longa; licebit<br>iniecto ter pulvere curras.", "st": "1.28"}, {"sp": "SEC", "t": "Carmen XXIX", "st": "1.29"}, {"sp": "N", "t": "Icci, beatis nunc Arabum invides<br>gazis et acrem militiam paras<br>non ante devictis Sabaeae<br>regibus horribilique Medo<br><br>nectis catenas? quae tibi virginum<br>sponso necato barbara serviet,<br>puer quis ex aula capillis<br>ad cyathum statuetur unctis<br><br>doctus sagittas tendere Sericas<br>arcu paterno? quis neget arduis<br>pronos relabi posse rivos<br>montibus et Tiberim reverti,<br><br>cum tu coemptos undique nobilis<br>libros Panaeti Socraticam et domum<br>mutare loricis Hiberis,<br>pollicitus meliora, tendis?", "st": "1.29"}, {"sp": "SEC", "t": "Carmen XXX", "st": "1.30"}, {"sp": "N", "t": "O Venus regina Cnidi Paphique,<br>sperne dilectam Cypron et vocantis<br>ture te multo Glycerae decoram<br>transfer in aedem.<br><br>fervidus tecum puer et solutis<br>Gratiae zonis properentque Nymphae<br>et parum comis sine te Iuventas<br>Mercuriusque.", "st": "1.30"}, {"sp": "SEC", "t": "Carmen XXXI", "st": "1.31"}, {"sp": "N", "t": "Quid dedicatum poscit Apollinem<br>vates? quid orat de patera novum<br>fundens liquorem? non opimae<br>Sardiniae segetes feracis,<br><br>non aestuosae grata Calabriae<br>armenta, non aurum aut ebur Indicum,<br>non rura, quae Liris quieta<br>mordet aqua taciturnus amnis.<br><br>premant Calenam falce quibus dedit<br>fortuna vitem, dives ut aureis<br>mercator exsiccet culillis<br>vina Syra reparata merce,<br><br>dis carus ipsis, quippe ter et quater<br>anno revisens aequor Atlanticum<br>inpune. me pascunt olivae,<br>me cichorea levesque malvae.<br><br>frui paratis et valido mihi,<br>Latoe, dones et precor integra<br>cum mente nec turpem senectam<br>degere nec cithara carentem.", "st": "1.31"}, {"sp": "SEC", "t": "Carmen XXXII", "st": "1.32"}, {"sp": "N", "t": "Poscimur. si quid vacui sub umbra<br>lusimus tecum, quod et hunc in annum<br>vivat et pluris, age dic Latinum,<br>barbite, carmen,<br><br>Lesbio primum modulate civi,<br>qui ferox bello tamen, inter arma<br>sive iactatam religarat udo<br>litore navim,<br><br>Liberum et Musas Veneremque et illi<br>semper haerentem puerum canebat<br>et Lycum nigris oculis nigroque<br>crine decorum.<br><br>o decus Phoebi et dapibus supremi<br>grata testudo Iovis, o laborum<br>dulce lenimen, mihi cumque salve<br>rite vocanti!", "st": "1.32"}, {"sp": "SEC", "t": "Carmen XXXIII", "st": "1.33"}, {"sp": "N", "t": "Albi, ne doleas plus nimio memor<br>inmitis Glycerae neu miserabilis<br>decantes elegos, cur tibi iunior<br>laesa praeniteat fide.<br><br>insignem tenui fronte Lycorida<br>Cyri torret amor, Cyrus in asperam<br>declinat Pholoen: sed prius Apulis<br>iungentur capreae lupis<br><br>quam turpi Pholoe peccet adultero.<br>sic visum Veneri, cui placet inpares<br>formas atque animos sub iuga aenea<br>saevo mittere cum ioco.<br><br>ipsum me melior cum peteret Venus,<br>grata detinuit compede Myrtale<br>libertina, fretis acrior Hadriae<br>curvantis Calabros sinus.", "st": "1.33"}, {"sp": "SEC", "t": "Carmen XXXIV", "st": "1.34"}, {"sp": "N", "t": "Parcus deorum cultor et infrequens,<br>insanientis dum sapientiae<br>consultus erro, nunc retrorsum<br>vela dare atque iterare cursus<br><br>cogor relictos: namque Diespiter,<br>igni corusco nubila dividens<br>plerumque, per purum tonantis<br>egit equos volucremque currum,<br><br>quo bruta tellus et vaga flumina,<br>quo Styx et invisi horrida Taenari<br>sedes Atlanteusque finis<br>concutitur. valet ima summis<br><br>mutare et insignem attenuat deus<br>obscura promens; hinc apicem rapax:<br>Fortuna cum stridore acuto<br>sustulit, hic posuisse gaudet.", "st": "1.34"}, {"sp": "SEC", "t": "Carmen XXXV", "st": "1.35"}, {"sp": "N", "t": "O diva, gratum quae regis Antium,<br>praesens vel imo tollere de gradu<br>mortale corpus vel superbos<br>vertere funeribus triumphos:<br><br>te pauper ambit sollicita prece<br>ruris colonus, te dominam aequoris<br>quicumque Bithyna lacessit<br>Carpathium pelagus carina;<br><br>te Dacus asper, te profugi Scythae<br>urbesque gentesque et Latium ferox<br>regumque matres barbarorum et<br>purpurei metuunt tyranni,<br><br>iniurioso ne pede proruas<br>stantem columnam neu populus frequens<br>ad arma, cessantis ad arma<br>concitet imperiumque frangat;<br><br>te semper anteit saeva Necessitas,<br>clavos trabalis et cuneos manu<br>gestans aena nec severus<br>uncus abest liquidumque plumbum;<br><br>te Spes et albo rara Fides colit<br>velata panno nec comitem abnegat,<br>utcumque mutata potentis<br>veste domos inimica linquis,<br><br>at volgus infidum et meretrix retro<br>periura cedit, diffugiunt cadis<br>cum faece siccatis amici,<br>ferre iugum pariter dolosi:<br><br>serves iturum Caesarem in ultimos<br>orbis Britannos et iuvenum recens<br>examen Eois timendum<br>partibus Oceanoque rubro.<br><br>heu heu, cicatricum et sceleris pudet<br>fratrumque. quid nos dura refugimus<br>aetas? quid intactum nefasti<br>liquimus? unde manum iuventus<br><br>metu deorum continuit? quibus<br>pepercit aris? o utinam nova<br>incude diffingas retusum in<br>Massagetas Arabasque ferrum.", "st": "1.35"}, {"sp": "SEC", "t": "Carmen XXXVI", "st": "1.36"}, {"sp": "N", "t": "Et ture et fidibus iuvat<br>placare et vituli sanguine debito<br>custodes Numidae deos,<br>qui nunc Hesperia sospes ab ultima<br>caris multa sodalibus,<br>nulli plura tamen dividet oscula<br>quam dulci Lamiae, memor<br>actae non alio rege puertiae<br>mutataeque simul togae.<br>Cressa ne careat pulcra dies nota<br>neu promptae modus amphorae<br>neu morem in Salium sit requies pedum<br>neu multi Damalis meri<br>Bassum Threicia vincat amystide<br>neu desint epulis rosae<br>neu vivax apium neu breve lilium.<br>omnes in Damalin putris<br>deponent oculos nec Damalis novo<br>divelletur adultero<br>lascivis hederis ambitiosior.", "st": "1.36"}, {"sp": "SEC", "t": "Carmen XXXVII", "st": "1.37"}, {"sp": "N", "t": "Nunc est bibendum, nunc pede libero<br>pulsanda tellus; nunc Saliaribus<br>ornare pulvinar deorum<br>tempus erat dapibus, sodales.<br><br>antehac nefas depromere Caecubum<br>cellis avitis, dum Capitolio<br>regina dementis ruinas,<br>funus et imperio parabat<br><br>contaminato cum grege turpium<br>morbo virorum quidlibet inpotens<br>sperare fortunaque dulci<br>ebria. sed minuit furorem<br><br>vix una sospes navis ab ignibus<br>mentemque lymphatam Mareotico<br>redegit in veros timores<br>Caesar ab Italia volantem<br><br>remis adurgens, accipiter velut<br>mollis columbas aut leporem citus<br>venator in campis nivalis<br>Haemoniae, daret ut catenis<br><br>fatale monstrum. quae generosius<br>perire quaerens nec muliebriter<br>expavit ensem nec latentis<br>classe cita reparavit oras.<br><br>ausa et iacentem visere regiam<br>voltu sereno, fortis et asperas<br>tractare serpentes, ut atrum<br>corpore conbiberet venenum,<br><br>deliberata morte ferocior;<br>saevis Liburnis scilicet invidens<br>privata deduci superbo,<br>non humilis mulier, triumpho.", "st": "1.37"}, {"sp": "SEC", "t": "Carmen XXXVIII", "st": "1.38"}, {"sp": "N", "t": "Persicos odi, puer, adparatus,<br>displicent nexae philyra coronae,<br>mitte sectari, rosa quo locorum<br>sera moretur.<br><br>simplici myrto nihil adlabores<br>sedulus curo: neque te ministrum<br>dedecet myrtus neque me sub arta<br>vite bibentem.", "st": "1.38"}, {"sp": "HDR", "t": "Liber II", "st": "2"}, {"sp": "SEC", "t": "Carmen I", "st": "2.1"}, {"sp": "N", "t": "Motum ex Metello consule civicum<br>bellique causas et vitia et modos<br>ludumque Fortunae gravisque<br>principum amicitias et arma<br><br>nondum expiatis uncta cruoribus,<br>periculosae plenum opus aleae,<br>tractas et incedis per ignis<br>suppositos cineri doloso.<br><br>paulum severae musa tragoediae<br>desit theatris: mox ubi publicas<br>res ordinaris, grande munus<br>Cecropio repetes cothurno,<br><br>insigne maestis praesidium reis<br>et consulenti, Pollio, curiae,<br>cui laurus aeternos honores<br>Delmatico peperit triumpho.<br><br>iam nunc minaci murmure cornuum<br>perstringis auris, iam litui strepunt,<br>iam fulgor armorum fugacis<br>terret equos equitumque voltus.<br><br>audire magnos iam videor duces,<br>non indecoro pulvere sordidos<br>et cuncta terrarum subacta<br>praeter atrocem animum Catonis.<br><br>Iuno et deorum quisquis amicior<br>Afris inulta cesserat inpotens<br>tellure victorum nepotes<br>rettulit inferias Iugurthae.<br><br>quis non Latino sanguine pinguior<br>campus sepulcris inpia proelia<br>testatur auditumque Medis<br>Hesperiae sonitum ruinae?<br><br>qui gurges aut quae flumina lugubris<br>ignara belli? quod mare Dauniae<br>non decoloravere caedes?<br>quae caret ora cruore nostro?<br><br>sed ne relictis, Musa procax, iocis<br>Ceae retractes munera neniae,<br>mecum Dionaeo sub antro<br>quaere modos leviore plectro.", "st": "2.1"}, {"sp": "SEC", "t": "Carmen II", "st": "2.2"}, {"sp": "N", "t": "Nullus argento color est avaris<br>abdito terris, inimice lamnae<br>Crispe Sallusti, nisi temperato<br>splendeat usu.<br><br>vivet extento Proculeius aevo,<br>notus in fratres animi paterni:<br>illum aget penna metuente solvi<br>Fama superstes.<br><br>latius regnes avidum domando<br>spiritum quam si Libyam remotis<br>Gadibus iungas et uterque Poenus<br>serviat uni.<br><br>crescit indulgens sibi dirus hydrops<br>nec sitim pellit, nisi causa morbi<br>fugerit venis et aquosus albo<br>corpore languor.<br><br>redditum Cyri solio Phraaten<br>dissidens plebi numero beatorum<br>eximit Virtus populumque falsis<br>dedocet uti<br><br>vocibus, regnum et diadema tutum<br>deferens uni propriamque laurum<br>quisquis ingentis oculo inretorto<br>spectat acervos.", "st": "2.2"}, {"sp": "SEC", "t": "Carmen III", "st": "2.3"}, {"sp": "N", "t": "Aequam memento rebus in arduis<br>servare mentem, non secus in bonis<br>ab insolenti temperatam<br>laetitia, moriture Delli,<br><br>seu maestus omni tempore vixeris<br>seu te in remoto gramine per dies<br>festos reclinatum bearis<br>interiore nota Falerni.<br><br>quo pinus ingens albaque populus<br>umbram hospitalem consociare amant<br>ramis? quid obliquo laborat<br>lympha fugax trepidare rivo?<br><br>huc vina et unguenta et nimium brevis<br>flores amoenae ferre iube rosae,<br>dum res et aetas et sororum<br>fila trium patiuntur atra.<br><br>cedes coemptis saltibus et domo<br>villaque, flavos quam Tiberis lavit,<br>cedes et exstructis in altum<br>divitiis potietur heres.<br><br>divesne prisco natus ab Inacho<br>nil interest an pauper et infima<br>de gente sub divo moreris:<br>victima nil miserantis Orci.<br><br>omnes eodem cogimur, omnium<br>versatur urna serius ocius<br>sors exitura et nos in aeternum<br>exilium inpositura cumbae.", "st": "2.3"}, {"sp": "SEC", "t": "Carmen IV", "st": "2.4"}, {"sp": "N", "t": "Ne sit ancillae tibi amor pudori,<br>Xanthia Phoceu: prius insolentem<br>serva Briseis niveo colore<br>movit Achillem,<br><br>movit Aiacem Telamone natum<br>forma captivae dominum Tecmessae,<br>arsit Atrides medio in triumpho<br>virgine rapta,<br><br>barbarae postquam cecidere turmae<br>Thessalo victore et ademptus Hector<br>tradidit fessis leviora tolli<br>Pergama Grais.<br><br>nescias an te generum beati<br>Phyllidis flavae decorent parentes:<br>regium certe genus, et penatis<br>maeret iniquos.<br><br>crede non illam tibi de scelesta<br>plebe dilectam neque sic fidelem,<br>sic lucro aversam potuisse nasci<br>matre pudenda.<br><br>bracchia et voltum teretesque suras<br>integer laudo: fuge suspicari,<br>cuius octavum trepidavit aetas<br>claudere lustrum.", "st": "2.4"}, {"sp": "SEC", "t": "Carmen VI", "st": "2.6"}, {"sp": "N", "t": "Septimi, Gadis aditure mecum et<br>Cantabrum indoctum iuga ferre nostra et<br>barbaras Syrtis, ubi Maura semper<br>aestuat unda:<br><br>Tibur Argeo positum colono<br>sit meae sedes utinam senectae,<br>sit modus lasso maris et viarum<br>militiaeque.<br><br>unde si Parcae prohibent iniquae,<br>dulce pellitis ovibus Galaesi<br>flumen et regnata petam Laconi<br>rura Phalantho<br><br>ille terrarum mihi praeter omnis<br>angulus ridet, ubi non Hymetto<br>mella decedunt viridique certat<br>baca Venafro,<br><br>ver ubi longum tepidasque praebet<br>Iuppiter brumas et amicus Aulon<br>fertili Baccho minimum Falernis<br>invidet uvis;<br><br>ille te mecum locus et beatae<br>postulant arces: ibi tu calentem<br>debita sparges lacrima favillam<br>vatis amici.", "st": "2.6"}, {"sp": "SEC", "t": "Carmen VII", "st": "2.7"}, {"sp": "N", "t": "O saepe mecum tempus in ultimum<br>deducte Bruto militiae duce,<br>quis te redonavit Quiritem<br>dis patriis Italoque caelo,<br><br>Pompei, meorum prime sodalium,<br>cum quo morantem saepe diem mero<br>fregi, coronatus nitentis<br>malobathro Syrio capillos?<br><br>tecum Philippos et celerem fugam<br>sensi relicta non bene parmula,<br>cum fracta virtus, et minaces<br>turpe solum tetigere mento;<br><br>sed me per hostis Mercurius celer<br>denso paventem sustulit aere,<br>te rursus in bellum resorbens<br>unda fretis tulit aestuosis.<br><br>ergo obligatam redde Iovi dapem<br>longaque fessum militia latus<br>depone sub lauru mea nec<br>parce cadis tibi destinatis.<br><br>oblivioso levia Massico<br>ciboria exple, funde capacibus<br>unguenta de conchis. quis udo<br>deproperare apio coronas<br><br>curatve myrto? quem Venus arbitrum<br>dicet bibendi? non ego sanius<br>bacchabor Edonis: recepto<br>dulce mihi furere est amico.", "st": "2.7"}, {"sp": "SEC", "t": "Carmen VIII", "st": "2.8"}, {"sp": "N", "t": "Vlla si iuris tibi peierati<br>poena, Barine, nocuisset umquam,<br>dente si nigro fieres vel uno<br>turpior ungui,<br><br>crederem: sed tu simul obligasti<br>perfidum votis caput, enitescis<br>pulchrior multo iuvenumque prodis<br>publica cura.<br><br>expedit matris cineres opertos<br>fallere et toto taciturna noctis<br>signa cum caelo gelidaque divos<br>morte carentis<br><br>ridet hoc, inquam, Venus ipsa, rident<br>simplices Nymphae, ferus et Cupido<br>semper ardentis acuens sagittas<br>cote cruenta.<br><br>adde quod pubes tibi crescit omnis,<br>servitus crescit nova nec priores<br>inpiae tectum dominae relinquunt,<br>saepe minati.<br><br>te suis matres metuunt iuvencis,<br>te senes parci miseraeque nuper<br>virgines nuptae, tua ne retardet<br>aura maritos.", "st": "2.8"}, {"sp": "SEC", "t": "Carmen IX", "st": "2.9"}, {"sp": "N", "t": "Non semper imbres nubibus hispidos<br>manant in agros aut mare Caspium<br>vexant inaequales procellae<br>usque nec Armeniis in oris,<br><br>amice Valgi, stat glacies iners<br>mensis per omnis aut Aquilonibus<br>querceta Gargani laborant<br>et foliis viduantur orni:<br><br>tu semper urges flebilibus modis<br>Mysten ademptum nec tibi Vespero<br>surgente decedunt amores<br>nec rapidum fugiente solem.<br><br>at non ter aevo functus amabilem<br>ploravit omnis Antilochum senex<br>annos nec inpubem parentes<br>Troilon aut Phrygiae sorores<br><br>flevere semper. desine mollium<br>tandem querellarum et potius nova<br>cantemus Augusti tropaea<br>Caesaris et rigidum Niphaten<br><br>Medumque flumen gentibus additum<br>victis minores volvere vertices<br>intraque praescriptum Gelonos<br>exiguis equitare campis.", "st": "2.9"}, {"sp": "SEC", "t": "Carmen X", "st": "2.10"}, {"sp": "N", "t": "Rectius vives, Licini, neque altum<br>semper urgendo neque, dum procellas<br>cautus horrescis, nimium premendo<br>litus iniquum.<br><br>auream quisquis mediocritatem<br>diligit, tutus caret obsoleti<br>sordibus tecti, caret invidenda<br>sobrius aula.<br><br>saepius ventis agitatur ingens<br>pinus et celsae graviore casu<br>decidunt turres feriuntque summos<br>fulgura montis<br><br>sperat infestis, metuit secundis<br>alteram sortem bene praeparatum<br>pectus. informis hiemes reducit<br>Iuppiter, idem<br><br>submovet. non, si male nunc, et olim<br>sic erit: quondam cithara tacentem<br>suscitat Musam neque semper arcum<br>tendit Apollo.<br><br>rebus angustis animosus atque<br>fortis adpare: sapienter idem<br>contrahes vento nimium secundo<br>turgida vela.", "st": "2.10"}, {"sp": "SEC", "t": "Carmen XI", "st": "2.11"}, {"sp": "N", "t": "Quid bellicosus Cantaber et Scythes,<br>Hirpine Quinti, cogitet Hadria<br>divisus obiecto, remittas<br>quaerere nec trepides in usum<br><br>poscentis aevi pauca: fugit retro<br>levis iuventas et decor arida<br>pellente lascivos amores<br>canitie facilemque somnum.<br><br>non semper idem floribus est honor<br>vernis neque uno luna rubens nitet<br>voltu: quid aeternis minorem<br>consiliis animum fatigas?<br><br>cur non sub alta vel platano vel hac<br>pinu iacentes sic temere et rosa<br>canos odorati capillos,<br>dum licet, Assyriaque nardo<br><br>potamus uncti? dissipat Euhius<br>curas edacis. quis puer ocius<br>restinguet ardentis Falerni<br>pocula praetereunte lympha?<br><br>quis devium scortum eliciet domo<br>Lyden? eburna, dic age, cum lyra<br>maturet, in comptum Lacaenae<br>more comam religata nodum.", "st": "2.11"}, {"sp": "SEC", "t": "Carmen XII", "st": "2.12"}, {"sp": "N", "t": "Nolis longa ferae bella Numantiae<br>nec durum Hannibalem nec Siculum mare<br>Poeno purpureum sanguine mollibus<br>aptari citharae modis<br><br>nec saevos Lapithas et nimium mero<br>Hylaeum domitosque Herculea manu<br>Telluris iuvenes, unde periculum<br>fulgens contremuit domus<br><br>Saturni veteris: tuque pedestribus<br>dices historiis proelia Caesaris,<br>Maecenas, melius ductaque per vias<br>regum colla minacium.<br><br>me dulcis dominae Musa Licymniae<br>cantus, me voluit dicere lucidum<br>fulgentis oculos et bene mutuis<br>fidum pectus amoribus;<br><br>quam nec ferre pedem dedecuit choris<br>nec certare ioco nec dare bracchia<br>ludentem nitidis virginibus sacro<br>Dianae celebris die.<br><br>num tu quae tenuit dives Achaemenes<br>aut pinguis Phrygiae Mygdonias opes<br>permutare velis crine Licymniae<br>plenas aut Arabum domos,<br><br>cum flagrantia detorquet ad oscula<br>cervicem aut facili saevitia negat<br>quae poscente magis gaudeat eripi,<br>interdum rapere occupet?", "st": "2.12"}, {"sp": "SEC", "t": "Carmen XIII", "st": "2.13"}, {"sp": "N", "t": "Ille et nefasto te posuit die<br>quicumque primum, et sacrilega manu<br>produxit, arbos, in nepotum<br>perniciem opprobriumque pagi;<br><br>illum et parentis crediderim sui<br>fregisse cervicem et penetralia<br>sparsisse nocturno cruore<br>hospitis; ille venena Colcha<br><br>et quidquid usquam concipitur nefas<br>tractavit, agro qui statuit meo<br>te, triste lignum, te, caducum<br>in domini caput inmerentis<br><br>quid quisque vitet, numquam homini satis<br>cautum est in horas: navita Bosporum<br>Poenus perhorrescit neque ultra<br>caeca timet aliunde fata,<br><br>miles sagittas et celerem fugam<br>Parthi, catenas Parthus et Italum<br>robur; sed inprovisa leti<br>vis rapuit rapietque gentis.<br><br>quam paene furvae regna Proserpinae<br>et iudicantem vidimus Aeacum<br>sedesque discriptas piorum et<br>Aeoliis fidibus querentem<br><br>Sappho puellis de popularibus<br>et te sonantem plenius aureo,<br>Alcaee, plectro dura navis,<br>dura fugae mala, dura belli.<br><br>utrumque sacro digna silentio<br>mirantur umbrae dicere, sed magis<br>pugnas et exactos tyrannos<br>densum umeris bibit aure volgus.<br><br>quid mirum, ubi illis carminibus stupens<br>demittit atras belua centiceps<br>auris et intorti capillis<br>Eumenidum recreantur angues?<br><br>quin et Prometheus et Pelopis parens<br>dulci laborem decipitur sono<br>nec curat Orion leones<br>aut timidos agitare lyncas", "st": "2.13"}, {"sp": "SEC", "t": "Carmen XIV", "st": "2.14"}, {"sp": "N", "t": "Eheu fugaces, Postume, Postume,<br>labuntur anni nec pietas moram<br>rugis et instanti senectae<br>adferet indomitaeque morti,<br><br>non, si trecenis quotquot eunt dies,<br>amice, places inlacrimabilem<br>Plutona tauris, qui ter amplum<br>Geryonen Tityonque tristi<br><br>conpescit unda, scilicet omnibus<br>quicumque terrae munere vescimur<br>enaviganda, sive reges<br>sive inopes erimus coloni.<br><br>frustra cruento Marte carebimus<br>fractisque rauci fluctibus Hadriae,<br>frustra per autumnos nocentem<br>corporibus metuemus Austrum:<br><br>visendus ater flumine languido<br>Cocytos errans et Danai genus<br>infame damnatusque longi<br>Sisyphus Aeolides laboris.<br><br>linquenda tellus et domus et placens<br>uxor neque harum quas colis arborum<br>te praeter invisas cupressos<br>ulla brevem dominum sequetur.<br><br>absumet heres Caecuba dignior<br>servata centum clavibus et mero<br>tinguet pavimentum superbo,<br>pontificum potiore cenis.", "st": "2.14"}, {"sp": "SEC", "t": "Carmen XV", "st": "2.15"}, {"sp": "N", "t": "Iam pauca aratro iugera regiae<br>moles relinquent, undique latius<br>extenta visentur Lucrino<br>stagna lacu platanusque caelebs<br><br>evincet ulmos; tum violaria et<br>myrtus et omnis copia narium<br>spargent olivetis odorem<br>fertilibus domino priori,<br><br>tum spissa ramis laurea fervidos<br>excludet ictus. non ita Romuli<br>praescriptum et intonsi Catonis<br>auspiciis veterumque norma.<br><br>privatus illis census erat brevis,<br>commune magnum: nulla decempedis<br>metata privatis opacam<br>porticus excipiebat arcton<br><br>nec fortuitum spernere caespitem<br>leges sinebant, oppida publico<br>sumptu iubentes et deorum<br>templa novo decorare saxo.", "st": "2.15"}, {"sp": "SEC", "t": "Carmen XVI", "st": "2.16"}, {"sp": "N", "t": "Otium divos rogat in patenti<br>prensus Aegaeo, simul atra nubes<br>condidit lunam neque certa fulgent<br>sidera nautis,<br><br>otium bello furiosa Thrace,<br>otium Medi pharetra decori,<br>Grosphe, non gemmis neque purpura ve-<br>nale nec auro.<br><br>non enim gazae neque consularis<br>submovet lictor miseros tumultus<br>mentis et curas laqueata circum<br>tecta volantis<br><br>vivitur parvo bene cui paternum<br>splendet in mensa tenui salinum<br>nec levis somnos timor aut cupido<br>sordidus aufert.<br><br>quid brevi fortes iaculamur aevo<br>multa? quid terras alio calentis<br>sole mutamus? patriae quis exsul<br>se quoque fugit?<br><br>scandit aeratas vitiosa navis<br>Cura nec turmas equitum relinquit<br>ocior cervis et agente nimbos<br>ocior Euro.<br><br>laetus in praesens animus quod ultra est<br>oderit curare et amara lento<br>temperet risu: nihil est ab omni<br>parte beatum.<br><br>abstulit clarum cita mors Achillem,<br>longa Tithonum minuit senectus<br>et mihi forsan tibi quod negarit<br>porriget hora.<br><br>te greges centum Siculaeque circum<br>mugiunt vaccae, tibi tollit hinnitum<br>apta quadrigis equa, te bis Afro<br>murice tinctae<br><br>vestiunt lanae: mihi parva rura et<br>spiritum Graiae tenuem Camenae<br>Parca non mendax dedit et malignum<br>spernere volgus.", "st": "2.16"}, {"sp": "SEC", "t": "Carmen XVII", "st": "2.17"}, {"sp": "N", "t": "Cur me querelis exanimas tuis?<br>nec dis amicum est nec mihi te prius<br>obire, Maecenas, mearum<br>grande decus columenque rerum.<br><br>a, te meae si partem animae rapit<br>maturior vis, quid moror altera,<br>nec carus aeque nec superstes<br>integer? ille dies utramque<br><br>ducet ruinam. non ego perfidum<br>dixi sacramentum ibimus, ibimus,<br>utcumque praecedes, supremum<br>carpere iter comites parati.<br><br>me nec Chimaerae spiritus igneae<br>nec si resurgat centimanus Gyas<br>divellet umquam: sic potenti<br>Iustitiae placitumque Parcis.<br><br>seu Libra seu me Scorpios adspicit<br>formidolosus pars violentior<br>natalis horae seu tyrannus<br>Hesperiae Capricornus undae:<br><br>utrumque nostrum incredibili modo<br>consentit astrum; te Iovis inpio<br>tutela Saturno refulgens<br>eripuit volucrisque Fati<br><br>tardavit alas, cum populus frequens<br>laetum theatris ter crepuit sonum;<br>me truncus inlapsus cerebro,<br>sustulerat, nisi Faunus ictum<br><br>dextra levasset, Mercurialium<br>custos virorum. reddere victimas<br>aedemque votivam memento;<br>nos humilem feriemus agnam.", "st": "2.17"}, {"sp": "SEC", "t": "Carmen XVIII", "st": "2.18"}, {"sp": "N", "t": "Non ebur neque aureum<br>mea renidet in domo lacunar,<br>non trabes Hymettiae<br>premunt columnas ultima recisas<br><br>Africa neque Attali<br>ignotus heres regiam occupavi<br>nec Laconicas mihi<br>trahunt honestae purpuras clientae.<br><br>at fides et ingeni<br>benigna vena est pauperemque dives<br>me petit: nihil supra<br>deos lacesso nec potentem amicum<br><br>largiora flagito,<br>satis beatus unicis Sabinis.<br>truditur dies die<br>novaeque pergunt interire lunae:<br><br>tu secanda marmora<br>locas sub ipsum funus et sepulcri<br>inmemor struis domos<br>marisque Bais obstrepentis urges<br><br>submovere litora,<br>parum locuples continente ripa;<br>quid quod usque proximos<br>revellis agri terminos et ultra<br><br>limites clientium<br>salis avarus? pellitur paternos<br>in sinu ferens deos<br>et uxor et vir sordidosque natos.<br><br>nulla certior tamen<br>rapacis Orci fine destinata<br>aula divitem manet<br>erum. quid ultra tendis? aequa tellus<br><br>pauperi recluditur<br>regumque pueris nec satelles Orci<br>callidum Promethea<br>revexit auro captus; hic superbum<br><br>Tantalum atque Tantali<br>genus coercet, hic levare functum<br>pauperem laboribus<br>vocatus atque non vocatus audit.", "st": "2.18"}, {"sp": "SEC", "t": "Carmen XIX", "st": "2.19"}, {"sp": "N", "t": "Bacchum in remotis carmina rupibus<br>vidi docentem, credite posteri,<br>Nymphasque discentis et auris<br>capripedum Satyrorum acutas<br><br>euhoe, recenti mens trepidat metu,<br>plenoque Bacchi pectore turbidum<br>laetatur. euhoe, parce Liber,<br>parce gravi metuende thyrso.<br><br>fas pervicacis est mihi Thyiadas<br>vinique fontem lactis et uberes<br>cantare rivos atque truncis<br>lapsa cavis iterare mella;<br><br>fas et beatae coniugis additum<br>stellis honorem tectaque Penthei<br>disiecta non leni ruina<br>Thracis et exitium Lycurgi<br><br>tu flectis amnis, tu mare barbarum,<br>tu separatis uvidus in iugis<br>nodo coerces viperino<br>Bistonidum sine fraude crinis.<br><br>tu, cum parentis regna per arduum<br>cohors gigantum scanderet inpia,<br>Rhoetum retorsisti leonis<br>unguibus horribilique mala;<br><br>quamquam choreis aptior et iocis<br>ludoque dictus non sat idoneus<br>pugnae ferebaris; sed idem<br>pacis eras mediusque belli.<br><br>te vidit insons Cerberus aureo<br>cornu decorum leniter atterens<br>caudam et recedentis trilingui<br>ore pedes tetigitque crura.", "st": "2.19"}, {"sp": "SEC", "t": "Carmen XX", "st": "2.20"}, {"sp": "N", "t": "Non usitata nec tenui ferar<br>penna biformis per liquidum aethera<br>vates neque in terris morabor<br>longius invidiaque maior<br><br>urbis relinquam. non ego, pauperum<br>sanguis parentum, non ego, quem vocas.<br>dilecte Maecenas, obibo<br>nec Stygia cohibebor unda.<br><br>iam iam residunt cruribus asperae<br>pelles et album mutor in alitem<br>superne nascunturque leves<br>per digitos umerosque plumae.<br><br>iam Daedaleo notior Icaro<br>visam gementis litora Bospori<br>Syrtisque Gaetulas canorus<br>ales Hyperboreosque campos.<br><br>me Colchus et qui dissimulat metum<br>Marsae cohortis Dacus et ultimi<br>noscent Geloni, me peritus<br>discet Hiber Rhodanique potor.<br><br>absint inani funere neniae<br>luctusque turpes et querimoniae;<br>conpesce clamorem ac sepulcri<br>mitte supervacuos honores.", "st": "2.20"}, {"sp": "HDR", "t": "Liber III", "st": "3"}, {"sp": "SEC", "t": "Carmen I", "st": "3.1"}, {"sp": "N", "t": "Odi profanum volgus et arceo.<br>favete linguis: carmina non prius<br>audita Musarum sacerdos<br>virginibus puerisque canto.<br><br>regum timendorum in proprios greges,<br>reges in ipsos imperium est Iovis,<br>clari Giganteo triumpho,<br>cuncta supercilio moventis.<br><br>est ut viro vir latius ordinet<br>arbusta sulcis, hic generosior<br>descendat in campum petitor,<br>moribus hic meliorque fama<br><br>contendat, illi turba clientium<br>sit maior: aequa lege Necessitas<br>sortitur insignis et imos,<br>omne capax movet urna nomen.<br><br>destrictus ensis cui super inpia<br>cervice pendet, non Siculae dapes<br>dulcem elaborabunt saporem,<br>non avium citharaeque cantus<br><br>somnum reducent: somnus agrestium<br>lenis virorum non humilis domos<br>fastidit umbrosamque ripam,<br>non Zephyris agitata Tempe.<br><br>desiderantem quod satis est neque<br>tumultuosum sollicitat mare<br>nec saevus Arcturi cadentis<br>impetus aut orientis Haedi,<br><br>non verberatae grandine vineae<br>fundusque mendax arbore nunc aquas<br>culpante, nunc torrentia agros<br>sidera, nunc hiemes iniquas.<br><br>contracta pisces aequora sentiunt<br>iactis in altum molibus: huc frequens<br>caementa demittit redemptor<br>cum famulis dominusque terrae<br><br>fastidiosus: sed Timor et Minae<br>scandunt eodem, quo dominus, neque<br>decedit aerata triremi et<br>post equitem sedet atra Cura.<br><br>quodsi dolentem nec Phrygius lapis<br>nec purpurarum sidere clarior<br>delenit usus nec Falerna<br>vitis Achaemeniumque costum,<br><br>cur invidendis postibus et novo<br>sublime ritu moliar atrium?<br>cur valle permutem Sabina<br>divitias operosiores?", "st": "3.1"}, {"sp": "SEC", "t": "Carmen II", "st": "3.2"}, {"sp": "N", "t": "Angustam amice pauperiem pati<br>robustus acri militia puer<br>condiscat et Parthos ferocis<br>vexet eques metuendus hasta<br><br>vitamque sub divo et trepidis agat<br>in rebus. illum ex moenibus hosticis<br>matrona bellantis tyranni<br>prospiciens et adulta virgo<br><br>suspiret “eheu, ne rudis agminum<br>sponsus lacessat regius asperum<br>tactu leonem, quem cruenta<br>per medias rapit ira caedes.”<br><br>dulce et decorum est pro patria mori:<br>mors et fugacem persequitur virum<br>nec parcit inbellis iuventae<br>poplitibus timidoque tergo.<br><br>Virtus, repulsae nescia sordidae,<br>intaminatis fulget honoribus<br>nec sumit aut ponit securis<br>arbitrio popularis aurae.<br><br>Virtus, recludens inmeritis mori<br>caelum, negata temptat iter via<br>coetusque volgaris et udam<br>spernit humum fugiente penna.<br><br>est et fideli tuta silentio<br>merces: vetabo, qui Cereris sacrum<br>volgarit arcanae, sub isdem<br>sit trabibus fragilemque mecum<br><br>solvat phaselon; saepe Diespiter<br>neglectus incesto addidit integrum,<br>raro antecedentem scelestum<br>deseruit pede Poena claudo.", "st": "3.2"}, {"sp": "SEC", "t": "Carmen III", "st": "3.3"}, {"sp": "N", "t": "Iustum et tenacem propositi virum<br>non civium ardor prava iubentium,<br>non voltus instantis tyranni<br>mente quatit solida neque Auster,<br><br>dux inquieti turbidus Hadriae,<br>nec fulminantis magna manus Iovis:<br>si fractus inlabatur orbis,<br>inpavidum ferient ruinae.<br><br>hac arte Pollux et vagus Hercules<br>enisus arcis attigit igneas,<br>quos inter Augustus recumbens<br>purpureo bibet ore nectar,<br><br>hac te merentem, Bacche pater, tuae<br>vexere tigres indocili iugum<br>collo trahentes, hac Quirinus<br>Martis equis Acheronta fugit,<br><br>gratum elocuta consiliantibus<br>Iunone divis: “Ilion, Ilion<br>fatalis incestusque iudex<br>et mulier peregrina vertit<br><br>in pulverem ex quo destituit deos<br>mercede pacta Laomedon, mihi<br>castaeque damnatum Minervae<br>cum populo et duce fraudulento.<br><br>iam nec Lacaenae splendet adulterae<br>famosus hospes nec Priami domus<br>periura pugnacis Achivos<br>Hectoreis opibus refringit<br><br>nostrisque ductum seditionibus<br>bellum resedit; protinus et gravis<br>iras et invisum nepotem,<br>Troica quem peperit sacerdos,<br><br>Marti redonabo; illum ego lucidas<br>inire sedes, discere nectaris<br>sucos et adscribi quietis<br>ordinibus patiar deorum.<br><br>dum longus inter saeviat Ilion<br>Romamque pontus, qualibet exsules<br>in parte regnanto beati;<br>dum Priami Paridisque busto<br><br>insultet armentum et catulos ferae<br>celent inultae, stet Capitolium<br>fulgens triumphatisque possit<br>Roma ferox dare iura Medis.<br><br>horrenda late nomen in ultimas<br>extendat oras, qua medius liquor<br>secernit Europen ab Afro,<br>qua tumidus rigat arva Nilus.<br><br>aurum inrepertum et sic melius situm,<br>cum terra celat, spernere fortior<br>quam cogere humanos in usus<br>omne sacrum rapiente dextra,<br><br>quicumque mundo terminus obstitit<br>hunc tanget armis, visere gestiens,<br>qua parte debacchentur ignes,<br>qua nebulae pluviique rores.<br><br>sed bellicosis fata Quiritibus<br>hac lege dico, ne nimium pii<br>rebusque fidentes avitae<br>tecta velint reparare Troiae.<br><br>Troiae renascens alite lugubri<br>fortuna tristi clade iterabitur<br>ducente victrices catervas<br>coniuge me Iovis et sorore.<br><br>ter si resurgat murus aeneus<br>auctore Phoebo, ter pereat meis<br>excisus Argivis, ter uxor<br>capta virum puerosque ploret”<br><br>non hoc iocosae conveniet lyrae —<br>quo, Musa, tendis? desine pervicax<br>referre sermones deorum et<br>magna modis tenuare parvis.", "st": "3.3"}, {"sp": "SEC", "t": "Carmen IV", "st": "3.4"}, {"sp": "N", "t": "Descende caelo et dic age tibia<br>regina longum Calliope melos,<br>seu voce nunc mavis acuta<br>seu fidibus citharave Phoebi.<br><br>auditis? an me ludit amabilis<br>insania? audire et videor pios<br>errare per lucos, amoenae<br>quos et aquae subeunt et aurae.<br><br>me fabulosae Volture in Apulo<br>nutricis extra limina Pulliae<br>ludo fatigatumque somno<br>fronde nova puerum palumbes<br><br>texere, mirum quod foret omnibus<br>quicumque celsae nidum Aceruntiae<br>saltusque Bantinos et arvum<br>pingue tenent humilis Forenti,<br><br>ut tuto ab atris corpore viperis<br>dormirem et ursis, ut premerer sacra<br>lauroque conlataque myrto<br>non sine dis animosus infans.<br><br>vester, Camenae, vester in arduos<br>tollor Sabinos, seu mihi frigidum<br>Praeneste seu Tibur supinum<br>seu liquidae placuere Baiae.<br><br>vestris amicum fontibus et choris<br>non me Philippis versa acies retro,<br>devota non extinxit arbor<br>nec Sicula Palinurus unda.<br><br>utcumque mecum vos eritis, libens<br>insanientem navita Bosporum<br>temptabo et urentis harenas<br>litoris Assyrii viator,<br><br>visam Britannos hospitibus feros<br>et laetum equino sanguine Concanum,<br>visam pharetratos Gelonos<br>et Scythicum inviolatus amnem.<br><br>vos Caesarem altum, militia simul<br>fessas cohortes abdidit oppidis,<br>finire quaerentem labores<br>Pierio recreatis antro.<br><br>vos lene consilium et datis et dato<br>gaudetis, almae. scimus, ut inpios<br>Titanas immanemque turbam<br>fulmine sustulerit caduco<br><br>qui terram inertem, qui mare temperat<br>ventosum et urbis regnaque tristia<br>divosque mortalisque turmas<br>imperio regit unus aequo.<br><br>magnum illa terrorem intulerat Iovi<br>fidens iuventus horrida bracchiis<br>fratresque tendentes opaco<br>Pelion inposuisse Olympo.<br><br>sed quid Typhoeus et validus Mimas<br>aut quid minaci Porphyrion statu,<br>quid Rhoetus evolsisque truncis<br>Enceladus iaculator audax<br><br>contra sonantem Palladis aegida<br>possent ruentes? hinc avidus stetit<br>Volcanus, hinc matrona Iuno et<br>numquam umeris positurus arcum<br><br>qui rore puro Castaliae lavit<br>crinis solutos, qui Lyciae tenet<br>dumeta natalemque silvam<br>Delius et Patareus Apollo.<br><br>vis consili expers mole ruit sua,<br>vim temperatam di quoque provehunt<br>in maius; idem odere viris<br>omne nefas animo moventis.<br><br>testis mearum centimanus Gyas<br>sententiarum, notus et integrae<br>temptator Orion Dianae<br>virginea domitus sagitta.<br><br>iniecta monstris Terra dolet suis<br>maeretque partus fulmine luridum<br>missos ad Orcum; nec peredit<br>inpositam celer ignis Aetnen<br><br>incontinentis nec Tityi iecur<br>reliquit ales, nequitiae additus<br>custos; amatorem trecentae<br>Pirithoum cohibent catenae.", "st": "3.4"}, {"sp": "SEC", "t": "Carmen V", "st": "3.5"}, {"sp": "N", "t": "Caelo tonantem credidimus Iovem<br>regnare; praesens divus habebitur<br>Augustus adiectis Britannis<br>imperio gravibusque Persis.<br><br>milesne Crassi coniuge barbara<br>turpis maritus vixit et hostium,<br>pro curia inversique mores!<br>consenuit socerorum in armis<br><br>sub rege Medo Marsus et Apulus,<br>anciliorum et nominis et togae<br>oblitus aeternaeque Vestae,<br>incolumi Iove et urbe Roma?<br><br>hoc caverat mens provida Reguli<br>dissentientis condicionibus<br>foedis et exemplo trahentis<br>perniciem veniens in aevum,<br><br>si non periret inmiserabilis<br>captiva pubes. “signa ego Punicis<br>adfixa delubris et arma<br>militibus sine caede” dixit<br><br>“derepta vidi, vidi ego civium<br>retorta tergo bracchia libero<br>portasque non clausas et arva<br>Marte coli populata nostro.<br><br>auro repensus scilicet acrior<br>miles redibit: flagitio additis<br>damnum; neque amissos colores<br>lana refert medicata fuco<br><br>nec vera virtus, cum semel excidit,<br>curat reponi deterioribus.<br>si pugnat extricata densis<br>cerva plagis, erit ille fortis<br><br>qui perfidis se credidit hostibus<br>et Marte Poenos proteret altero;<br>qui lora restrictis lacertis<br>sensit iners timuitque mortem,<br><br>hic, unde vitam sumeret inscius,<br>pacem duello miscuit. o pudor!<br>o magna Carthago, probrosis<br>altior Italiae ruinis!”<br><br>fertur pudicae coniugis osculum<br>parvosque natos ut capitis minor<br>ab se removisse et virilem<br>torvus humi posuisse voltum,<br><br>donec labantis consilio patres<br>firmaret auctor numquam alias dato<br>interque maerentis amicos<br>egregius properaret exul.<br><br>atqui sciebat, quae sibi barbarus<br>tortor pararet: non aliter tamen<br>dimovit obstantis propinquos<br>et populum reditus morantem<br><br>quam si clientum longa negotia<br>diiudicata lite relinqueret<br>tendens Venafranos in agros<br>aut Lacedaemonium Tarentum.", "st": "3.5"}, {"sp": "SEC", "t": "Carmen VI", "st": "3.6"}, {"sp": "N", "t": "Delicta maiorum inmeritus lues,<br>Romane, donec templa refeceris<br>aedisque labentis deorum et<br>foeda nigro simulacra fumo.<br><br>dis te minorem quod geris, imperas:<br>hinc omne principium, huc refer exitum:<br>di multa neglecti dederunt<br>Hesperiae mala luctuosae.<br><br>iam bis Monaeses et Pacori manus<br>inauspicatos contudit impetus<br>nostros et adiecisse praedam<br>torquibus exiguis renidet.<br><br>paene occupatam seditionibus<br>delevit urbem Dacus et Aethiops,<br>hic classe formidatus, ille<br>missilibus melior sagittis.<br><br>fecunda culpae saecula nuptias<br>primum inquinavere et genus et domos:<br>hoc fonte derivata clades<br>in patriam populumque fluxit.<br><br>motus doceri gaudet Ionicos<br>matura virgo et fingitur artibus<br>iam nunc et incestos amores<br>de tenero meditatur ungui.<br><br>mox iuniores quaerit adulteros<br>inter mariti vina neque eligit<br>cui donet inpermissa raptim<br>gaudia luminibus remotis,<br><br>sed iussa coram non sine conscio<br>surgit marito, seu vocat institor<br>seu navis Hispanae magister,<br>dedecorum pretiosus emptor.<br><br>non his iuventus orta parentibus<br>infecit aequor sanguine Punico<br>Pyrrhumque et ingentem cecidit<br>Antiochum Hannibalemque dirum,<br><br>sed rusticorum mascula militum<br>proles, Sabellis docta ligonibus<br>versare glaebas et severae<br>matris ad arbitrium recisos<br><br>portare fustis, sol ubi montium<br>mutaret umbras et iuga demeret<br>bubus fatigatis amicum<br>tempus agens abeunte curru.<br><br>damnosa quid non inminuit dies?<br>aetas parentum, peior avis, tulit<br>nos nequiores, mox daturos<br>progeniem vitiosiorem.", "st": "3.6"}, {"sp": "SEC", "t": "Carmen VII", "st": "3.7"}, {"sp": "N", "t": "Quid fles, Asterie, quem tibi, candidi<br>primo restituent vere Favonii<br>Thyna merce beatum,<br>constantis iuvenem fide<br><br>Gygen? ille Notis actus ad Oricum<br>post insana Caprae sidera frigidas<br>noctis non sine multis<br>insomnis lacrimis agit.<br><br>atqui sollicitae nuntius hospitae,<br>suspirare Chloen et miseram tuis<br>dicens ignibus uri,<br>temptat mille vafer modis:<br><br>ut Proetum mulier perfida credulum<br>falsis inpulerit criminibus nimis<br>casto Bellerophontae<br>maturare necem, refert;<br><br>narrat paene datum Pelea Tartaro,<br>Magnessam Hippolyten dum fugit abstinens,<br>et peccare docentis<br>fallax historias movet.<br><br>frustra: nam scopulis surdior Icari<br>voces audit adhuc integer. at tibi<br>ne vicinus Enipeus<br>plus iusto placeat cave;<br><br>quamvis non alius flectere equum sciens<br>aeque conspicitur gramine Martio,<br>nec quisquam citus aeque<br>Tusco denatat alveo.<br><br>prima nocte domum claude neque in vias<br>sub cantu querulae despice tibiae<br>et te saepe vocanti<br>duram difficilis mane.", "st": "3.7"}, {"sp": "SEC", "t": "Carmen VIII", "st": "3.8"}, {"sp": "N", "t": "Martiis caelebs quid agam kalendis,<br>quid velint flores et acerra turis<br>plena miraris positusque carbo in<br>caespite vivo,<br><br>docte sermones utriusque linguae?<br>voveram dulcis epulas et album<br>Libero caprum prope funeratus<br>arboris ictu.<br><br>hic dies anno redeunte festus<br>corticem adstrictum pice dimovebit<br>amphorae fumum bibere institutae<br>consule Tullo.<br><br>sume, Maecenas, cyathos amici<br>sospitis centum et vigiles lucernas<br>perfer in lucem: procul omnis esto<br>clamor et ira.<br><br>mitte civilis super urbe curas:<br>occidit Daci Cotisonis agmen,<br>Medus infestus sibi luctuosis<br>dissidet armis,<br><br>servit Hispanae vetus hostis orae<br>Cantaber, sera domitus catena,<br>iam Scythae laxo meditantur arcu<br>cedere campis.<br><br>neglegens, ne qua populus laboret,<br>parce privatus nimium cavere et<br>dona praesentis cape laetus horae,<br>linque severa.", "st": "3.8"}, {"sp": "SEC", "t": "Carmen IX", "st": "3.9"}, {"sp": "N", "t": "“Donec gratus eram tibi<br>nec quisquam potior bracchia candidae<br>cervici iuvenis dabat,<br>Persarum vigui rege beatior.”", "st": "3.9"}, {"sp": "N", "t": "“donec non alia magis<br>arsisti neque erat Lydia post Chloen,<br>multi Lydia nominis,<br>Romana vigui clarior Ilia.”", "st": "3.9"}, {"sp": "N", "t": "“me nunc Thressa Chloe regit,<br>dulcis docta modos et citharae sciens,<br>pro qua non metuam mori,<br>si parcent animae fata superstiti”", "st": "3.9"}, {"sp": "N", "t": "“me torret face mutua<br>Thurini Calais filius Ornyti,<br>pro quo bis patiar mori,<br>si parcent puero fata superstiti.”", "st": "3.9"}, {"sp": "N", "t": "“quid si prisca redit Venus<br>diductosque iugo cogit aeneo?<br>si flava excutitur Chloe<br>reiectaeque patet ianua Lydiae?”", "st": "3.9"}, {"sp": "N", "t": "“quamquam sidere pulchrior<br>ille est, tu levior cortice et inprobo<br>iracundior Hadria:<br>tecum vivere amem, tecum obeam lubens.”", "st": "3.9"}, {"sp": "SEC", "t": "Carmen X", "st": "3.10"}, {"sp": "N", "t": "Extremum Tanain si biberes, Lyce,<br>saevo nupta viro, me tamen asperas<br>porrectum ante foris obicere incolis<br>plorares Aquilonibus<br><br>audis, quo strepitu ianua, quo nemus<br>inter pulcra satum tecta remugiat<br>ventis et positas ut glaciet nives<br>puro numine Iuppiter?<br><br>ingratam Veneri pone superbiam,<br>ne currente retro funis eat rota:<br>non te Penelopen difficilem procis<br>Tyrrhenus genuit parens.<br><br>o quamvis neque te munera nec preces<br>nec tinctus viola pallor amantium<br>nec vir Pieria paelice saucius<br>curvat, supplicibus tuis<br><br>parcas, nec rigida mollior aesculo<br>nec Mauris animum mitior anguibus:<br>non hoc semper erit liminis aut aquae<br>caelestis patiens latus.", "st": "3.10"}, {"sp": "SEC", "t": "Carmen XI", "st": "3.11"}, {"sp": "N", "t": "Mercuri, nam te docilis magistro<br>movit Amphion lapides canendo,<br>tuque testudo resonare septem<br>callida nervis,<br><br>nec loquax olim neque grata, nunc et<br>divitum mensis et amica templis,<br>dic modos, Lyde quibus obstinatas<br>adplicet auris,<br><br>quae velut latis equa trima campis<br>ludit exsultim metuitque tangi<br>nuptiarum expers et adhuc protervo<br>cruda marito.<br><br>tu potes tigris comitesque silvas<br>ducere et rivos celeres morari;<br>cessit immanis tibi blandienti<br>ianitor aulae<br><br>Cerberus, quamvis furiale centum<br>muniant angues caput eius atque<br>spiritus taeter saniesque manet<br>ore trilingui;<br><br>quin et Ixion Tityosque voltu<br>risit invito, stetit urna paulum<br>sicca, dum grato Danai puellas<br>carmine mulces.<br><br>audiat Lyde scelus atque notas<br>virginum poenas et inane lymphae<br>dolium fundo pereuntis imo<br>seraque fata,<br><br>quae manent culpas etiam sub Orco.<br>inpiae, (nam quid potuere maius?)<br>inpiae sponsos potuere duro<br>perdere ferro.<br><br>una de multis face nuptiali<br>digna periurum fuit in parentem<br>splendide mendax et in omne virgo<br>nobilis aevum,<br><br>“surge” quae dixit iuveni marito,<br>“surge, ne longus tibi somnus unde<br>non times detur; socerum et scelestas<br>falle sorores,<br><br>quae velut nactae vitulos leaenae<br>singulos eheu lacerant: ego illis<br>mollior nec te feriam neque intra<br>claustra tenebo.<br><br>me pater saevis oneret catenis,<br>quod viro clemens misero peperci,<br>me vel extremos Numidarum in agros<br>classe releget:<br><br>i pedes quo te rapiunt et aurae,<br>dum favet nox et Venus, i secundo<br>omine et nostri memorem sepulcro<br>scalpe querelam.”", "st": "3.11"}, {"sp": "SEC", "t": "Carmen XII", "st": "3.12"}, {"sp": "N", "t": "Miserarum est neque amori dare ludum neque dulci<br>mala vino lavere, aut exanimari metuentis<br>patruae verbera linguae.<br><br>tibi qualum Cythereae puer ales, tibi telas<br>operosaeque Minervae studium aufert, Neobule,<br>Liparaei nitor Hebri,<br><br>simul unctos Tiberinis umeros lavit in undis,<br>eques ipso melior Bellerophonte, neque pugno<br>neque segni pede victus,<br><br>catus idem per apertum fugientis agitato<br>grege cervos iaculari et celer arto latitantem<br>fruticeto excipere aprum.", "st": "3.12"}, {"sp": "SEC", "t": "Carmen XIII", "st": "3.13"}, {"sp": "N", "t": "O fons Bandusiae splendidior vitro,<br>dulci digne mero non sine floribus,<br>cras donaberis haedo,<br>cui frons turgida cornibus<br><br>primis et venerem et proelia destinat;<br>frustra: nam gelidos inficiet tibi<br>rubro sanguine rivos<br>lascivi suboles gregis.<br><br>te flagrantis atrox hora Caniculae<br>nescit tangere, tu frigus amabile<br>fessis vomere tauris<br>praebes et pecori vago.<br><br>fies nobilium tu quoque fontium<br>me dicente cavis inpositam ilicem<br>saxis, unde loquaces<br>lymphae desiliunt tuae.", "st": "3.13"}, {"sp": "SEC", "t": "Carmen XIV", "st": "3.14"}, {"sp": "N", "t": "Herculis ritu modo dictus, o plebs,<br>morte venalem petiisse laurum<br>Caesar Hispana repetit penatis<br>victor ab ora.<br><br>unico gaudens mulier marito<br>prodeat iustis operata sacris<br>et soror clari ducis et decorae<br>supplice vitta<br><br>virginum matres iuvenumque nuper<br>sospitum; vos, o pueri et puellae<br>iam virum expertae, male nominatis<br>parcite verbis.<br><br>hic dies vere mihi festus atras<br>exiget curas ego nec tumultum<br>nec mori per vim metuam tenente<br>Caesare terras.<br><br>i pete unguentum, puer, et coronas<br>et cadum Marsi memorem duelli,<br>Spartacum siqua potuit vagantem<br>fallere testa.<br><br>dic et argutae properet Neaerae<br>murreum nodo cohibere crinem;<br>si per invisum mora ianitorem<br>fiet, abito.<br><br>lenit albescens animos capillus<br>litium et rixae cupidos protervae;<br>non ego hoc ferrem calidus iuventa<br>consule Planco.", "st": "3.14"}, {"sp": "SEC", "t": "Carmen XV", "st": "3.15"}, {"sp": "N", "t": "Uxor pauperis Ibyci,<br>tandem nequitiae fige modum tuae<br>famosisque laboribus;<br>maturo propior desine funeri<br><br>inter ludere virgines<br>et stellis nebulam spargere candidis.<br>non, siquid Pholoen, satis<br>et te, Chlori, decet: filia rectius<br><br>expugnat iuvenum domos,<br>pulso Thyias uti concita tympano.<br>illam cogit amor Nothi<br>lascivae similem ludere capreae,<br><br>te lanae prope nobilem<br>tonsae Luceriam, non citharae decent<br>nec flos purpureus rosae<br>nec poti, vetulam, faece tenus cadi.", "st": "3.15"}, {"sp": "SEC", "t": "Carmen XVI", "st": "3.16"}, {"sp": "N", "t": "Inclusam Danaen turris aenea<br>robustaeque fores et vigilum canum<br>tristes excubiae munierant satis<br>nocturnis ab adulteris,<br><br>si non Acrisium virginis abditae<br>custodem pavidum Iuppiter et Venus<br>risissent: fore enim tutum iter et patens<br>converso in pretium deo.<br><br>aurum per medios ire satellites<br>et perrumpere amat saxa potentius<br>ictu fulmineo: concidit auguris<br>Argivi domus ob lucrum<br><br>demersa exitio; diffidit urbium<br>portas vir Macedo et subruit aemulos<br>reges muneribus; munera navium<br>saevos inlaqueant duces.<br><br>crescentem sequitur cura pecuniam<br>maiorumque fames. iure perhorrui<br>late conspicuum tollere verticem,<br>Maecenas, equitum decus.<br><br>quanto quisque sibi plura negaverit,<br>ab dis plura feret nil cupientium<br>nudus castra peto et transfuga divitum<br>partis linquere gestio,<br><br>contemptae dominus splendidior rei,<br>quam si quidquid arat inpiger Apulus<br>occultare meis dicerer horreis,<br>magnas inter opes inops.<br><br>purae rivos aquae silvaque iugerum<br>paucorum et segetis certa fides meae<br>fulgentem imperio fertilis Africae<br>fallit sorte beatior.<br><br>quamquam nec Calabrae mella ferunt apes<br>nec Laestrygonia Bacchus in amphora<br>languescit mihi nec pinguia Gallicis<br>crescunt vellera pascuis:<br><br>inportuna tamen pauperies abest<br>nec, si plura velim, tu dare deneges.<br>contracto melius parva cupidine<br>vectigalia porrigam<br><br>quam si Mygdoniis regnum Alyattei<br>campis continuem. multa petentibus<br>desunt multa: bene est cui deus obtulit<br>parca quod satis est manu.", "st": "3.16"}, {"sp": "SEC", "t": "Carmen XVII", "st": "3.17"}, {"sp": "N", "t": "Aeli vetusto nobilis ab Lamo,<br>quando et priores hinc Lamias ferunt<br>denominatos et nepotum<br>per memores genus omne fastos,<br><br>auctore ab illo ducis originem,<br>qui Formiarum moenia dicitur<br>princeps et innantem Maricae<br>litoribus tenuisse Lirim,<br><br>late tyrannus:— cras foliis nemus<br>multis et alga litus inutili<br>demissa tempestas ab Euro<br>sternet, aquae nisi fallit augur<br><br>annosa cornix. dum potes, aridum<br>conpone lignum: cras genium mero<br>curabis et porco bimenstri<br>cum famulis operum solutis.", "st": "3.17"}, {"sp": "SEC", "t": "Carmen XVIII", "st": "3.18"}, {"sp": "N", "t": "Faune, Nympharum fugientum amator,<br>per meos finis et aprica rura<br>lenis incedas abeasque parvis<br>aequus alumnis,<br><br>si tener pleno cadit haedus anno<br>larga nec desunt Veneris sodali<br>vina craterae, vetus ara multo<br>fumat odore.<br><br>ludit herboso pecus omne campo<br>cum tibi nonae redeunt Decembres,<br>festus in pratis vacat otioso<br>cum bove pagus,<br><br>inter audacis lupus errat agnos,<br>spargit agrestis tibi silva frondes,<br>gaudet invisam pepulisse fossor<br>ter pede terram.", "st": "3.18"}, {"sp": "SEC", "t": "Carmen XIX", "st": "3.19"}, {"sp": "N", "t": "Quantum distet ab Inacho<br>Codrus pro patria non timidus mori<br>narras et genus Aeaci<br>et pugnata sacro bella sub Ilio:<br><br>quo Chium pretio cadum<br>mercemur, quis aquam temperet ignibus,<br>quo praebente domum et quota<br>Paelignis caream frigoribus, taces.<br><br>da lunae propere novae,<br>da noctis mediae, da, puer, auguris<br>Murenae: tribus aut novem<br>miscentur cyathis pocula commodis.<br><br>qui Musas amat imparis,<br>ternos ter cyathos attonitus petet<br>vates; tris prohibet supra<br>rixarum metuens tangere Gratia<br><br>nudis iuncta sororibus.<br>insanire iuvat: cur Berecyntiae<br>cessant flamina tibiae?<br>cur pendet tacita fistula cum lyra?<br><br>parcentis ego dexteras<br>odi: sparge rosas, audiat invidus<br>dementem strepitum Lycus<br>et vicina seni non habilis Lyco.<br><br>spissa te nitidum coma,<br>puro te similem, Telephe, Vespero<br>tempestiva petit Rhode;<br>me lentus Glycerae torret amor meae.", "st": "3.19"}, {"sp": "SEC", "t": "Carmen XXI", "st": "3.21"}, {"sp": "N", "t": "O nata mecum consule Manlio,<br>seu tu querellas sive geris iocos<br>seu rixam et insanos amores<br>seu facilem, pia testa, somnum,<br><br>quocumque lectum nomine Massicum<br>servas, moveri digna bono die,<br>descende Corvino iubente<br>promere languidiora vina.<br><br>non ille, quamquam Socraticis madet<br>sermonibus, te neglegit horridus:<br>narratur et prisci Catonis<br>saepe mero caluisse virtus.<br><br>tu lene tormentum ingenio admoves<br>plerumque duro, tu sapientium<br>curas et arcanum iocoso<br>consilium retegis Lyaeo,<br><br>tu spem reducis mentibus anxiis<br>virisque et addis cornua pauperi<br>post te neque iratos trementi<br>regum apices neque militum arma.<br><br>te Liber et si laeta aderit Venus<br>segnesque nodum solvere Gratiae<br>vivaeque producent lucernae,<br>dum rediens fugat astra Phoebus.", "st": "3.21"}, {"sp": "SEC", "t": "Carmen XXII", "st": "3.22"}, {"sp": "N", "t": "Montium custos nemorumque, virgo,<br>quae laborantis utero puellas<br>ter vocata audis adimisque leto,<br>diva triformis,<br><br>imminens villae tua pinus esto,<br>quam per exactos ego laetus annos<br>verris obliquum meditantis ictum<br>sanguine donem.", "st": "3.22"}, {"sp": "SEC", "t": "Carmen XXIII", "st": "3.23"}, {"sp": "N", "t": "Caelo supinas si tuleris manus<br>nascente luna, rustica Phidyle,<br>si ture placaris et horna<br>fruge Laris avidaque porca:<br><br>nec pestilentem sentiet Africum<br>fecunda vitis nec sterilem seges<br>robiginem aut dulces alumni<br>pomifero grave tempus anno.<br><br>nam quae nivali pascitur Algido<br>devota quercus inter et ilices<br>aut crescit Albanis in herbis<br>victima, pontificum securis<br><br>cervice tinguet: te nihil attinet<br>temptare multa caede bidentium<br>parvos coronantem marino<br>rore deos fragilique myrto.<br><br>inmunis aram si tetigit manus,<br>non sumptuosa blandior hostia,<br>mollivit aversos Penatis<br>farre pio et saliente mica.", "st": "3.23"}, {"sp": "SEC", "t": "Carmen XXIV", "st": "3.24"}, {"sp": "N", "t": "Intactis opulentior<br>thesauris Arabum et divitis Indiae<br>caementis licet occupes<br>terrenum omne tuis et mare publicum:<br><br>si figit adamantinos<br>summis verticibus dira Necessitas<br>clavos, non animum metu,<br>non mortis laqueis expedies caput.<br><br>campestres melius Scythae,<br>quorum plaustra vagas rite trahunt domos<br>vivunt et rigidi Getae,<br>inmetata quibus iugera liberas<br><br>fruges et Cererem ferunt<br>nec cultura placet longior annua<br>defunctumque laboribus<br>aequali recreat sorte vicarius.<br><br>illic matre carentibus<br>privignis mulier temperat innocens<br>nec dotata regit virum<br>coniunx nec nitido fidit adultero;<br><br>dos est magna parentium<br>virtus et metuens alterius viri<br>certo foedere castitas,<br>et peccare nefas aut pretium est mori.<br><br>o quisquis volet inpias<br>caedis et rabiem tollere civicam,<br>si quaeret pater urbium<br>subscribi statuis, indomitam audeat<br><br>refrenare licentiam,<br>clarus postgenitis: quatenus, heu nefas<br>virtutem incolumem odimus,<br>sublatam ex oculis quaerimus invidi.<br><br>quid tristes querimoniae,<br>si non supplicio culpa reciditur,<br>quid leges sine moribus<br>vanae proficiunt, si neque fervidis<br><br>pars inclusa caloribus<br>mundi nec Boreae finitimum latus<br>durataeque solo nives<br>mercatorem abigunt, horrida callidi<br><br>vincunt aequora navitae,<br>magnum pauperies opprobrium iubet<br>quidvis et facere et pati<br>virtutisque viam deserit arduae?<br><br>vel nos in Capitolium,<br>quo clamor vocat et turba faventium,<br>vel nos in mare proximum<br>gemmas et lapides aurum et inutile,<br><br>summi materiem mali,<br>mittamus, scelerum si bene paenitet.<br>eradenda cupidinis<br>pravi sunt elementa et tenerae nimis<br><br>mentes asperioribus<br>formandae studiis. nescit equo rudis<br>haerere ingenuus puer<br>venarique timet, ludere doctior,<br><br>seu Graeco iubeas trocho<br>seu malis vetita legibus alea,<br>cum periura patris fides<br>consortem socium fallat et hospites<br><br>indignoque pecuniam<br>heredi properet. scilicet inprobae<br>crescunt divitiae, tamen<br>curtae nescio quid semper abest rei.", "st": "3.24"}, {"sp": "SEC", "t": "Carmen XXV", "st": "3.25"}, {"sp": "N", "t": "Quo me, Bacche, rapis tui<br>plenum? quae nemora aut quos agor in specus,<br>velox mente nova? quibus<br>antris egregii Caesaris audiar<br><br>aeternum meditans decus<br>stellis inserere et consilio Iovis?<br>dicam insigne, recens, adhuc<br>indictum ore alio. non secus in iugis<br><br>exsomnis stupet Euhias<br>Hebrum prospiciens et nive candidam<br>Thracen ac pede barbaro<br>lustratam Rhodopen, ut mihi devio<br><br>ripas et vacuum nemus<br>mirari libet. o Naiadum potens<br>Baccharumque valentium<br>proceras manibus vertere fraxinos,<br><br>nil parvum aut humili modo,<br>nil mortale loquar. dulce periculum est,<br>o Lenaee, sequi deum<br>cingentem viridi tempora pampino.", "st": "3.25"}, {"sp": "SEC", "t": "Carmen XXVI", "st": "3.26"}, {"sp": "N", "t": "Vixi puellis nuper idoneus<br>et militavi non sine gloria;<br>nunc arma defunctumque bello<br>barbiton hic paries habebit,<br><br>laevum marinae qui Veneris latus<br>custodit. hic, hic ponite lucida<br>funalia et vectis et arcus<br>oppositis foribus minacis.<br><br>o quae beatam diva tenes Cyprum et<br>Memphin carentem Sithonia nive,<br>regina, sublimi flagello<br>tange Chloen semel arrogantem.", "st": "3.26"}, {"sp": "SEC", "t": "Carmen XXVII", "st": "3.27"}, {"sp": "N", "t": "Inpios parrae recinentis omen<br>ducat et praegnans canis aut ab agro<br>rava decurrens lupa Lanuvino<br>fetaque volpes;<br><br>rumpat et serpens iter institutum,<br>si per obliquum similis sagittae<br>terruit mannos: ego cui timebo,<br>providus auspex,<br><br>antequam stantis repetat paludes<br>imbrium divina avis imminentium,<br>oscinem corvum prece suscitabo<br>solis ab ortu.<br><br>sis licet felix, ubicumque mavis,<br>et memor nostri, Galatea, vivas<br>teque nec laevos vetet ire picus<br>nec vaga cornix.<br><br>sed vides, quanto trepidet tumultu<br>pronus Orion. ego quid sit ater<br>Hadriae novi sinus et quid albus<br>peccet Iapyx.<br><br>hostium uxores puerique caecos<br>sentiant motus orientis Austri et<br>aequoris nigri fremitum et trementis<br>verbere ripas.<br><br>sic et Europe niveum doloso<br>credidit tauro latus et scatentem<br>beluis pontum mediasque fraudes<br>palluit audax.<br><br>nuper in pratis studiosa florum et<br>debitae Nymphis opifex coronae<br>nocte sublustri nihil astra praeter<br>vidit et undas.<br><br>quae simul centum tetigit potentem<br>oppidis Creten, “pater, o relictum<br>filiae nomen pietasque” dixit<br>“victa furore!<br><br>unde quo veni? levis una mors est<br>virginum culpae. vigilansne ploro<br>turpe conmissum an vitiis carentem<br>ludit imago<br><br>vana, quae porta fugiens eburna<br>somnium ducit? meliusne fluctus<br>ire per longos fuit an recentis<br>carpere flores?<br><br>siquis infamem mihi nunc iuvencum<br>dedat iratae, lacerare ferro et<br>frangere enitar modo multum amati<br>cornua monstri.<br><br>inpudens liqui patrios Penates,<br>inpudens Orcum moror. o deorum<br>siquis haec audis, utinam inter errem<br>nuda leones.<br><br>antequam turpis macies decentis<br>occupet malas teneraeque sucus<br>defluat praedae, speciosa quaero<br>pascere tigris<br><br>“vilis Europe” pater urget absens:<br>“quid mori cessas? potes hac ab orno<br>pendulum zona bene te secuta<br>laedere collum.<br><br>sive te rupes et acuta leto<br>saxa delectant, age te procellae<br>crede veloci, nisi erile mavis<br>carpere pensum<br><br>regius sanguis dominaeque tradi<br>barbarae paelex.”” aderat querenti<br>perfidum ridens Venus et remisso<br>filius arcu.<br><br>mox ubi lusit satis, “abstineto”<br>dixit “irarum calidaeque rixae,<br>cum tibi invisus laceranda reddet<br>cornua taurus.<br><br>uxor invicti Iovis esse nescis.<br>mitte singultus, bene ferre magnam<br>disce fortunam; tua sectus orbis<br>nomina ducet.”", "st": "3.27"}, {"sp": "SEC", "t": "Carmen XXVIII", "st": "3.28"}, {"sp": "N", "t": "Festo quid potius die<br>Neptuni faciam? prome reconditum,<br>Lyde, strenua Caecubum,<br>munitaeque adhibe vim sapientiae.<br><br>inclinare meridiem<br>sentis et, veluti stet volucris dies,<br>parcis deripere horreo<br>cessantem Bibuli consulis amphoram.<br><br>nos cantabimus invicem<br>Neptunum et viridis Nereidum comas;<br>tu curva recines lyra<br>Latonam et celeris spicula Cynthiae;<br><br>summo carmine quae Cnidon<br>fulgentisque tenet Cycladas et Paphon<br>iunctis visit oloribus<br>dicetur, merita Nox quoque nenia.", "st": "3.28"}, {"sp": "SEC", "t": "Carmen XXIX", "st": "3.29"}, {"sp": "N", "t": "Tyrrhena regum progenies, tibi<br>non ante verso lene merum cado<br>cum flore, Maecenas, rosarum et<br>pressa tuis balanus capillis<br><br>iamdudum apud me est: eripe te morae<br>ne semper udum Tibur et Aefulae<br>declive contempleris arvum et<br>Telegoni iuga parricidae.<br><br>fastidiosam desere copiam et<br>molem propinquam nubibus arduis,<br>omitte mirari beatae<br>fumum et opes strepitumque Romae.<br><br>plerumque gratae divitibus vices<br>mundaeque parvo sub lare pauperum<br>cenae sine aulaeis et ostro<br>sollicitam explicuere frontem.<br><br>Iam clarus occultum Andromedae pater<br>ostendit ignem, iam Procyon furit<br>et stella vesani Leonis,<br>sole dies referente siccos;<br><br>iam pastor umbras cum grege languido<br>rivumque fessus quaerit et horidi<br>dumeta Silvani, caretque<br>ripa vagis taciturna ventis.<br><br>tu civitatem quis deceat status<br>curas et urbi sollicitus times<br>quid Seres et regnata Cyro<br>Bactra parent Tanaisque discors.<br><br>prudens futuri temporis exitum<br>caliginosa nocte premit deus<br>ridetque, si mortalis ultra<br>fas trepidat. quod adest memento<br><br>conponere aequos; cetera fluminis<br>ritu feruntur, nunc medio alveo<br>cum pace delabentis Etruscum<br>in mare, nunc lapides adesos<br><br>stirpisque raptas et pecus et domos<br>volventis una, non sine montium<br>clamore vicinaeque silvae,<br>cum fera diluvies quietos<br><br>inritat amnis. ille potens sui<br>laetusque deget cui licet in diem<br>dixisse “vixi: cras vel atra<br>nube polum pater occupato<br><br>vel sole puro; non tamen inritum<br>quodcumque retro est efficiet neque<br>diffinget infectumque reddet<br>quod fugiens semel hora vexit.”<br><br>Fortuna saevo laeta negotio et<br>ludum insolentem ludere pertinax<br>transmutat incertos honores,<br>nunc mihi nunc alii benigna.<br><br>laudo manentem; si celeres quatit<br>pennas, resigno quae dedit et mea<br>virtute me involvo probamque<br>pauperiem sine dote quaero.<br><br>non est meum, si mugiat Africis<br>malus procellis, ad miseras preces<br>decurrere et votis pacisci<br>ne Cypriae Tyriaeque merces<br><br>addant avaro divitias mari:<br>tunc me biremis praesidio scaphae<br>tutum per Aegaeos tumultus<br>aura feret geminusque Pollux.", "st": "3.29"}, {"sp": "SEC", "t": "Carmen XXX", "st": "3.30"}, {"sp": "N", "t": "Exegi monumentum aere perennius<br>regalique situ pyramidum altius,<br>quod non imber edax, non aquilo impotens<br>possit diruere aut innumerabilis<br>annorum series et fuga temporum.<br>non omnis moriar multaque pars mei<br>vitabit Libitinam; usque ego postera<br>crescam laude recens, dum Capitolium<br>scandet cum tacita virgine pontifex.<br>dicar, qua violens obstrepit Aufidus<br>et qua pauper aquae Daunus agrestium<br>regnavit populorum, ex humili potens,<br>princeps Aeolium carmen ad Italos<br>deduxisse modos. sume superbiam<br>quaesitam meritis et mihi Delphica<br>lauro cinge volens, Melpomene, comam.", "st": "3.30"}, {"sp": "HDR", "t": "Liber IV", "st": "4"}, {"sp": "SEC", "t": "Carmen I", "st": "4.1"}, {"sp": "N", "t": "Intermissa, Venus, diu<br>rursus bella moves? parce, precor precor.<br>non sum qualis eram bonae<br>sub regno Cinarae. desine, dulcium<br><br>mater saeva Cupidinum,<br>circa lustra decem flectere mollibus<br>iam durum imperiis: abi,<br>quo blandae iuvenum te revocant preces.<br><br>tempestivius in domum<br>Pauli purpureis ales oloribus<br>comissabere Maximi,<br>si torrere iecur quaeris idoneum;<br><br>namque et nobilis et decens<br>et pro sollicitis non tacitus reis<br>et centum puer artium<br>late signa feret militiae tuae<br><br>et, quandoque potentior<br>largi muneribus riserit aemuli,<br>Albanos prope te lacus<br>ponet marmoream sub trabe citrea.<br><br>illic plurima naribus<br>duces tura lyraeque et Berecyntiae<br>delectabere tibiae<br>mixtis carminibus non sine fistula;<br><br>illic bis pueri die<br>numen cum teneris virginibus tuum<br>laudantes pede candido<br>in morem Salium ter quatient humum.<br><br>me nec femina nec puer<br>iam nec spes animi credula mutui<br>nec certare iuvat mero<br>nec vincire novis tempora floribus.<br><br>sed cur heu, Ligurine, cur<br>manat rara meas lacrima per genas?<br>cur facunda parum decoro<br>inter verba cadit lingua silentio?<br><br>nocturnis ego somniis<br>iam captum teneo, iam volucrem sequor<br>te per gramina Martii<br>campi, te per aquas, dure, volubilis.", "st": "4.1"}, {"sp": "SEC", "t": "Carmen II", "st": "4.2"}, {"sp": "N", "t": "Pindarum quisquis studet aemulari,<br>Iulle, ceratis ope Daedalea<br>nititur pennis vitreo daturus<br>nomina ponto.<br><br>monte decurrens velut amnis, imbres<br>quem super notas aluere ripas,<br>fervet inmensusque ruit profundo<br>Pindarus ore,<br><br>laurea donandus Apollinari,<br>seu per audacis nova dithyrambos<br>verba devolvit numerisque fertur<br>lege solutis,<br><br>seu deos regesque canit, deorum<br>sanguinem, per quos cecidere iusta<br>morte Centauri, cecidit tremendae<br>flamma Chimaerae,<br><br>sive quos Elea domum reducit<br>palma caelestis pugilemve equomve<br>dicit et centum potiore signis<br>munere donat,<br><br>flebili sponsae iuvenemve raptum<br>plorat et viris animumque moresque<br>aureos educit in astra nigroque<br>invidet Orco.<br><br>multa Dircaeum levat aura cycnum,<br>tendit, Antoni, quotiens in altos<br>nubium tractus: ego apis Matinae<br>more modoque<br><br>grata carpentis thyma per laborem<br>plurimum circa nemus uvidique<br>Tiburis ripas operosa parvos<br>carmina fingo.<br><br>concines maiore poeta plectro<br>Caesarem, quandoque trahet ferocis<br>per sacrum clivum merita decorus<br>fronde Sygambros;<br><br>quo nihil maius meliusve terris<br>fata donavere bonique divi<br>nec dabunt, quamvis redeant in aurum<br>tempora priscum.<br><br>concines laetosque dies et urbis<br>publicum ludum super inpetrato<br>fortis Augusti reditu forumque<br>litibus orbum.<br><br>tum meae, si quid loquar audiendum,<br>vocis accedet bona pars et “o sol<br>pulcher, o laudande!” canam recepto<br>Caesare felix.<br><br>teque, dum procedis, “Io Triumphe”<br>non semel dicemus, “Io Triumphe”<br>civitas omnis dabimusque divis<br>tura benignis.<br><br>te decem tauri totidemque vaccae,<br>me tener solvet vitulus, relicta<br>matre qui largis iuvenescit herbis<br>in mea vota,<br><br>fronte curvatos imitatus ignis<br>tertium lunae referentis ortum,<br>qua notam duxit, niveus videri,<br>cetera fulvos.", "st": "4.2"}, {"sp": "SEC", "t": "Carmen III", "st": "4.3"}, {"sp": "N", "t": "Quem tu, Melpomene, semel<br>nascentem placido lumine videris,<br>illum non labor Isthmius<br>clarabit pugilem, non equos inpiger<br><br>curru ducet Achaico<br>victorem neque res bellica Deliis<br>ornatum foliis ducem,<br>quod regum tumidas contuderit minas,<br><br>ostendet Capitolio:<br>sed quae Tibur aquae fertile praefluunt<br>et spissae nemorum comae<br>fingent Aeolio carmine nobilem.<br><br>Romae principis urbium<br>dignatur suboles inter amabilis<br>vatum ponere me choros<br>et iam dente minus mordeor invido.<br><br>o testudinis aureae<br>dulcem quae strepitum, Pieri, temperas,<br>o mutis quoque piscibus<br>donatura cycni, si libeat, sonum,<br><br>totum muneris hoc tui est,<br>quod monstror digito praetereuntium<br>Romanae fidicen lyrae:<br>quod spiro et placeo, si placeo, tuum est.", "st": "4.3"}, {"sp": "SEC", "t": "Carmen IV", "st": "4.4"}, {"sp": "N", "t": "Qualem ministrum fulminis alitem,<br>cui rex deorum regnum in avis vagas<br>permisit expertus fidelem<br>Iuppiter in Ganymede flavo,<br><br>olim iuventas et patrius vigor<br>nido laborum propulit inscium,<br>vernique iam nimbis remotis<br>insolitos docuere nisus<br><br>venti paventem, mox in ovilia<br>demisit hostem vividus impetus,<br>nunc in reluctantis dracones<br>egit amor dapis atque pugnae;<br><br>qualemve laetis caprea pascuis<br>intenta fulvae matris ab ubere<br>iam lacte depulsum leonem<br>dente novo peritura vidit:<br><br>videre Raetis bella sub Alpibus<br>Drusum gerentem Vindelici. quibus<br>mos unde deductus per omne<br>tempus Amazonia securi<br><br>dextras obarmet, quaerere distuli<br>nec scire fas est omnia, sed diu<br>lateque victrices catervae<br>consiliis iuvenis revictae<br><br>sensere, quid mens rite, quid indoles<br>nutrita faustis sub penetralibus<br>posset, quid Augusti paternus<br>in pueros animus Nerones.<br><br>fortes creantur fortibus et bonis:<br>est in iuvencis, est in equis patrum<br>virtus neque inbellem feroces<br>progenerant aquilae columbam.<br><br>doctrina sed vim promovet insitam<br>rectique cultus pectora roborant;<br>utcumque defecere mores,<br>indecorant bene nata culpae.<br><br>quid debeas, o Roma, Neronibus,<br>testis Metaurum flumen et Hasdrubal<br>devictus et pulcher fugatis<br>ille dies Latio tenebris,<br><br>qui primus alma risit adorea,<br>dirus per urbis Afer ut Italas<br>ceu flamma per taedas vel Eurus<br>per Siculas equitavit undas.<br><br>post hoc secundis usque laboribus<br>Romana pubes crevit et inpio<br>vastata Poenorum tumultu<br>fana deos habuere rectos.<br><br>dixitque tandem perfidus Hannibal:<br>“cervi, luporum praeda rapacium,<br>sectamur ultro quos opimus<br>fallere et effugere est triumphus.<br><br>gens, quae cremato fortis ab Ilio<br>iactata Tuscis aequoribus sacra<br>natosque maturosque patres<br>pertulit Ausonias ad urbis,<br><br>duris ut ilex tonsa bipennibus<br>nigrae feraci frondis in Algido,<br>per damna, per caedis ab ipso<br>ducit opes animumque ferro.<br><br>non hydra secto corpore firmior<br>vinci dolentem crevit in Herculem<br>monstrumve submisere Colchi<br>maius Echioniaeve Thebae.<br><br>merses profundo, pulchrior evenit;<br>luctere, multa proruet integrum<br>cum laude victorem geretque<br>proelia coniugibus loquenda.<br><br>Carthagini iam non ego nuntios<br>mittam superbos: occidit, occidit<br>spes omnis et fortuna nostri<br>nominis Hasdrubale interempto.<br><br>nil Claudiae non perficient manus,<br>quas et benigno numine Iuppiter<br>defendit et curae sagaces<br>expediunt per acuta belli”.", "st": "4.4"}, {"sp": "SEC", "t": "Carmen V", "st": "4.5"}, {"sp": "N", "t": "Divis orte bonis, optume Romulae<br>custos gentis, abes iam nimium diu;<br>maturum reditum pollicitus patrum<br>sancto concilio redi.<br><br>lucem redde tuae, dux bone, patriae:<br>instar veris enim voltus ubi tuus<br>adfulsit populo, gratior it dies<br>et soles melius nitent.<br><br>ut mater iuvenem, quem Notus invido<br>flatu Carpathii trans maris aequora<br>cunctantem spatio longius annuo<br>dulci distinet a domo,<br><br>votis ominibusque et precibus vocat<br>curvo nec faciem litore dimovet:<br>sic desideriis icta fidelibus<br>quaerit patria Caesarem.<br><br>tutus bos etenim rura perambulat,<br>nutrit rura Ceres almaque Faustitas,<br>pacatum volitant per mare navitae;<br>culpari metuit fides,<br><br>nullis polluitur casta domus stupris,<br>mos et lex maculosum edomuit nefas,<br>laudantur simili prole puerperae,<br>culpam poena premit comes.<br><br>quis Parthum paveat, quis gelidum Scythen,<br>quis Germania quos horrida parturit<br>fetus incolumi Caesare? quis ferae<br>bellum curet Hiberiae?<br><br>condit quisque diem collibus in suis<br>et vitem viduas ducit ad arbores;<br>hinc ad vina redit laetus et alteris<br>te mensis adhibet deum;<br><br>te multa prece, te prosequitur mero<br>defuso pateris et Laribus tuum<br>miscet numen, uti Graecia Castoris<br>et magni memor Herculis.<br><br>“longas o utinam, dux bone, ferias<br>praestes Hesperiae!” dicimus integro<br>sicci mane die, dicimus uvidi,<br>cum sol Oceano subest.", "st": "4.5"}, {"sp": "SEC", "t": "Carmen VI", "st": "4.6"}, {"sp": "N", "t": "Dive, quem proles Niobea magnae<br>vindicem linguae Tityosque raptor<br>sensit et Troiae prope victor altae<br>Pthius Achilles,<br><br>ceteris maior, tibi miles inpar,<br>filius quamvis Thetidis marinae<br>Dardanas turris quateret tremenda<br>cuspide pugnax—<br><br>ille, mordaci velut icta ferro<br>pinus aut inpulsa cupressus Euro,<br>procidit late posuitque collum in<br>pulvere Teucro;<br><br>ille non inclusus equo Minervae<br>sacra mentito male feriatos<br>Troas et laetam Priami choreis<br>falleret aulam,<br><br>sed palam captis gravis, heu nefas, heu,<br>nescios fari pueros Achivis<br>ureret flammis, etiam latentem<br>matris in alvo,<br><br>ni tuis victus Venerisque gratae<br>vocibus divum pater adnuisset<br>rebus Aeneae potiore ductos<br>alite muros.<br><br>doctor argutae fidicen Thaliae<br>Phoebe, qui Xantho lavis amne crinis,<br>Dauniae defende decus Camenae,<br>levis Agyieu.<br><br>spiritum Phoebus, mihi Phoebus artem<br>carminis nomenque dedit poetae.<br>virginum primae puerique claris<br>patribus orti,<br><br>Deliae tutela deae, fugacis<br>lyncas et cervos cohibentis arcu,<br>Lesbium servate pedem meique<br>pollicis ictum<br><br>rite Latonae puerum canentes,<br>rite crescentem face Noctilucam,<br>prosperam frugum celeremque pronos<br>volvere mensis.<br><br>nupta iam dices “ego dis amicum<br>saeculo festas referente luces<br>reddidi carmen docilis modorum<br>vatis Horati.”", "st": "4.6"}, {"sp": "SEC", "t": "Carmen VII", "st": "4.7"}, {"sp": "N", "t": "Diffugere nives, redeunt iam gramina campis<br>arboribusque comae;<br>mutat terra vices et decrescentia ripas<br>flumina praetereunt;<br><br>Gratia cum Nymphis geminisque sororibus audet<br>ducere nuda choros:<br>inmortalia ne speres, monet annus et almum<br>quae rapit hora diem.<br><br>frigora mitescunt Zephyris, ver proterit aestas<br>interitura, simul<br>pomifer autumnus fruges effuderit, et mox<br>bruma recurrit iners.<br><br>damna tamen celeres reparant caelestia lunae:<br>nos ubi decidimus<br>quo pius Aeneas, quo dives Tullus et Ancus,<br>pulvis et umbra sumus.<br><br>quis scit an adiciant hodiernae crastina summae<br>tempora di superi?<br>cuncta manus avidas fugient heredis amico<br>quae dederis animo.<br><br>cum semel occideris et de te splendida Minos<br>fecerit arbitria,<br>non, Torquate, genus, non te facundia, non te<br>restituet pietas;<br><br>infernis neque enim tenebris Diana pudicum<br>liberat Hippolytum<br>nec Lethaea valet Theseus abrumpere caro<br>vincula Pirithoo.", "st": "4.7"}, {"sp": "SEC", "t": "Carmen VIII", "st": "4.8"}, {"sp": "N", "t": "Donarem pateras grataque commodus,<br>Censorine, meis aera sodalibus,<br>donarem tripodas, praemia fortium<br>Graiorum, neque tu pessuma munerum<br>ferres, divite me scilicet artium<br>quas aut Parrhasius protulit aut Scopas,<br>hic saxo, liquidis ille coloribus<br>sollers nunc hominem ponere, nunc deum<br>sed non haec mihi vis, nec tibi talium<br>res est aut animus deliciarum egens.<br>gaudes carminibus; carmina possumus<br>donare et pretium dicere muneri.<br>non incisa notis marmora publicis,<br>per quae spiritus et vita redit bonis<br>post mortem ducibus, non “celeres fugae<br>reiectaeque retrorsum Hannibalis minae”<br>non “incendia Karthaginis inpiae”,<br>eius, “qui domita nomen ab Africa<br>lucratus rediit”, clarius indicant<br>laudes quam “Calabrae Pierides” neque,<br>si chartae sileant quod bene feceris,<br>mercedem tuleris. quid foret Iliae<br>Mavortisque puer, si taciturnitas<br>obstaret meritis invida Romuli?<br>ereptum Stygiis fluctibus Aeacum<br>virtus et favor et lingua potentium<br>vatum divitibus consecrat insulis.<br>dignum laude virum Musa vetat mori,<br>caelo Musa beat. sic Iovis interest<br>optatis epulis inpiger Hercules,<br>clarum Tyndaridae sidus ab infimis<br>quassas eripiunt aequoribus ratis,<br>ornatus viridi tempora pampino<br>Liber vota bonos ducit ad exitus.", "st": "4.8"}, {"sp": "SEC", "t": "Carmen IX", "st": "4.9"}, {"sp": "N", "t": "Ne forte credas interitura quae<br>longe sonantem natus ad Aufidum<br>non ante volgatas per artis<br>verba loquor socianda chordis:<br><br>non, si priores Maeonius tenet<br>sedes Homerus, Pindaricae latent<br>Ceaeque et Alcaei minaces<br>Stesichorique graves Camenae<br><br>nec siquid olim lusit Anacreon<br>delevit aetas; spirat adhuc amor<br>vivuntque conmissi calores<br>Aeoliae fidibus puellae.<br><br>non sola comptos arsit adulteri<br>crinis et aurum vestibus inlitum<br>mirata regalisque cultus<br>et comites Helene Lacaena<br><br>primusve Teucer tela Cydonio<br>direxit arcu; non semel Ilios<br>vexata; non pugnavit ingens<br>Idomeneus Sthenelusve solus<br><br>dicenda Musis proelia; non ferox<br>Hector vel acer Deiphobus gravis<br>excepit ictus pro pudicis<br>coniugibus puerisque primus.<br><br>vixere fortes ante Agamemnona<br>multi; sed omnes inlacrimabiles<br>urgentur ignotique longa<br>nocte, carent quia vate sacro.<br><br>paullum sepultae distat inertiae<br>celata virtus. non ego te meis<br>chartis inornatum silebo,<br>totve tuos patiar labores<br><br>inpune, Lolli, carpere lividas<br>obliviones. est animus tibi<br>rerumque prudens et secundis<br>temporibus dubiisque rectus,<br><br>vindex avarae fraudis et abstinens<br>ducentis ad se cuncta pecuniae,<br>consulque non unius anni,<br>sed quotiens bonus atque fidus<br><br>iudex honestum praetulit utili,<br>reiecit alto dona nocentium<br>voltu, per obstantis catervas<br>explicuit sua victor arma.<br><br>non possidentem multa vocaveris<br>recte beatum; rectius occupat<br>nomen beati qui deorum<br>muneribus sapienter uti<br><br>duramque callet pauperiem pati<br>peiusque leto flagitium timet,<br>non ille pro caris amicis<br>aut patria timidus perire.", "st": "4.9"}, {"sp": "SEC", "t": "Carmen XI", "st": "4.11"}, {"sp": "N", "t": "Est mihi nonum superantis annum<br>plenus Albani cadus, est in horto,<br>Phylli, nectendis apium coronis;<br>est hederae vis<br><br>multa, qua crinis religata fulges,<br>ridet argento domus, ara castis<br>vincta verbenis avet immolato<br>spargier agno;<br><br>cuncta festinat manus, huc et illuc<br>cursitant mixtae pueris puellae,<br>sordidum flammae trepidant rotantes<br>vertice fumum.<br><br>ut tamen noris, quibus advoceris<br>gaudiis: Idus tibi sunt agendae,<br>qui dies mensem Veneris marinae<br>findit Aprilem,<br><br>iure sollemnis mihi sanctiorque<br>paene natali proprio, quod ex hac<br>luce Maecenas meus adfluentis<br>ordinat annos.<br><br>Telephum, quem tu petis, occupavit<br>non tuae sortis iuvenem puella<br>dives et lasciva tenetque grata<br>compede vinctum.<br><br>terret ambustus Phaethon avaras<br>spes et exemplum grave praebet ales<br>Pegasus terrenum equitem gravatus<br>Bellerophontem,<br><br>semper ut te digna sequare et ultra<br>quam licet sperare nefas putando<br>disparem vites. age iam, meorum<br>finis amorum,<br><br>(non enim posthac alia calebo<br>femina) condisce modos, amanda<br>voce quos reddas: minuentur atrae<br>carmine curae.", "st": "4.11"}, {"sp": "SEC", "t": "Carmen XII", "st": "4.12"}, {"sp": "N", "t": "Iam veris comites, quae mare temperant,<br>inpellunt animae lintea Thraciae,<br>iam nec prata rigent nec fluvii strepunt<br>hiberna nive turgidi.<br><br>nidum ponit, Ityn flebiliter gemens,<br>infelix avis et Cecropiae domus<br>aeternum opprobrium, quod male barbaras<br>regum est ulta libidines.<br><br>dicunt in tenero gramine pinguium<br>custodes ovium carmina fistula<br>delectantque deum, cui pecus et nigri<br>colles Arcadiae placent.<br><br>adduxere sitim tempora, Vergili:<br>sed pressum Calibus ducere Liberum<br>si gestis, iuvenum nobilium cliens,<br>nardo vina merebere.<br><br>nardi parvus onyx eliciet cadum,<br>qui nunc Sulpiciis adcubat horreis,<br>spes donare novas largus amaraque<br>curarum eluere efficax.<br><br>ad quae si properas gaudia, cum tua<br>velox merce veni: non ego te meis<br>inmunem meditor tinguere poculis,<br>plena dives ut in domo.<br><br>verum pone moras et studium lucri<br>nigrorumque memor, dum licet, ignium<br>misce stultitiam consiliis brevem:<br>dulce est desipere in loco.", "st": "4.12"}, {"sp": "SEC", "t": "Carmen XIII", "st": "4.13"}, {"sp": "N", "t": "Audivere, Lyce, di mea vota, di<br>audivere, Lyce: fis anus et tamen<br>vis formosa videri<br>ludisque et bibis inpudens<br><br>et cantu tremulo pota Cupidinem<br>lentum sollicitas. ille virentis et<br>doctae psallere Chiae<br>pulcris excubat in genis.<br><br>inportunus enim transvolat aridas<br>quercus et refugit te quia luridi<br>dentes, te quia rugae<br>turpant et capitis nives.<br><br>nec Coae referunt iam tibi purpurae<br>nec cari lapides tempora, quae semel<br>notis condita fastis<br>inclusit volucris dies.<br><br>quo fugit venus, heu, quove color, decens<br>quo motus? quid habes illius, illius,<br>quae spirabat amores,<br>quae me surpuerat mihi<br><br>felix post Cinaram notaque et artium<br>gratarum facies? sed Cinarae brevis<br>annos fata dederunt,<br>servatura diu parem<br><br>cornicis vetulae temporibus Lycen,<br>possent ut iuvenes visere fervidi<br>multo non sine risu<br>dilapsam in cineres facem.", "st": "4.13"}, {"sp": "SEC", "t": "Carmen XIV", "st": "4.14"}, {"sp": "N", "t": "Quae cura patrum quaeve Quiritium<br>plenis honorum muneribus tuas,<br>Auguste, virtutes in aevum<br>per titulos memoresque fastos<br><br>aeternet, o, qua sol habitabilis<br>inlustrat oras, maxime principum,<br>quem legis expertes Latinae<br>Vindelici didicere nuper<br><br>quid Marte posses. milite nam tuo<br>Drusus Genaunos, inplacidum genus,<br>Breunosque velocis et arcis<br>Alpibus inpositas tremendis<br><br>deiecit acer plus vice simplici;<br>maior Neronum mox grave proelium<br>conmisit immanisque Raetos<br>auspiciis pepulit secundis,<br><br>spectandus in certamine Martio<br>devota morti pectora liberae<br>quantis fatigaret ruinis,<br>indomitas prope qualis undas<br><br>exercet Auster Pleiadum choro<br>scindente nubis, inpiger hostium<br>vexare turmas et frementem<br>mittere equum medios per ignis.<br><br>sic tauriformis volvitur Aufidus,<br>qui regna Dauni praefluit Apuli,<br>cum saevit horrendamque cultis<br>diluviem meditatur agris,<br><br>ut barbarorum Claudius agmina<br>ferrata vasto diruit impetu<br>primosque et extremos metendo<br>stravit humum sine clade victor,<br><br>te copias, te consilium et tuos<br>praebente divos. nam tibi quo die<br>portus Alexandrea supplex<br>et vacuam patefecit aulam,<br><br>Fortuna lustro prospera tertio<br>belli secundos reddidit exitus<br>laudemque et optatum peractis<br>imperiis decus adrogavit.<br><br>te Cantaber non ante domabilis<br>Medusque et Indus, te profugus Scythes<br>miratur, o tutela praesens<br>Italiae dominaeque Romae.<br><br>te fontium qui celat origines<br>Nilusque et Hister, te rapidus Tigris,<br>te beluosus qui remotis<br>obstrepit Oceanus Britannis,<br><br>te non paventis funera Galliae<br>duraeque tellus audit Hiberiae,<br>te caede gaudentes Sygambri<br>conpositis venerantur armis.", "st": "4.14"}, {"sp": "SEC", "t": "Carmen XV", "st": "4.15"}, {"sp": "N", "t": "Phoebus volentem proelia me loqui<br>victas et urbis increpuit lyra,<br>ne parva Tyrrhenum per aequor<br>vela darem. tua, Caesar, aetas<br><br>fruges et agris rettulit uberes<br>et signa nostro restituit Iovi<br>derepta Parthorum superbis<br>postibus et vacuum duellis<br><br>Ianum Quirini clausit et ordinem<br>rectum evaganti frena licentiae<br>iniecit emovitque culpas<br>et veteres revocavit artis,<br><br>per quas Latinum nomen et Italae<br>crevere vires famaque et imperi<br>porrecta maiestas ad ortus<br>solis ab Hesperio cubili.<br><br>custode rerum Caesare non furor<br>civilis aut vis exiget otium,<br>non ira, quae procudit ensis<br>et miseras inimicat urbis.<br><br>non qui profundum Danuvium bibunt<br>edicta rumpent Iulia, non Getae,<br>non Seres infidique Persae,<br>non Tanain prope flumen orti.<br><br>nosque et profestis lucibus et sacris<br>inter iocosi munera Liberi<br>cum prole matronisque nostris,<br>rite deos prius adprecati,<br><br>virtute functos more patrum duces<br>Lydis remixto carmine tibiis<br>Troiamque et Anchisen et almae<br>progeniem Veneris canemus.", "st": "4.15"}, {"sp": "SEC", "t": "Carmen Saeculare", "st": "CS"}, {"sp": "N", "t": "Phoebe silvarumque potens Diana,<br>Lucidum caeli decus, o colendi<br>Semper et culti, date quae precamur<br>Tempore sacro,<br><br>Quo Sibyllini monuere versus<br>Virgines lectas puerosque castos<br>Dis quibus septem placuere colles<br>Dicere carmen.<br><br>Alme Sol, curru nitido diem qui<br>Promis et celas aliusque et idem<br>Nasceris, possis nihil urbe Roma<br>Visere maius!<br><br>Rite maturos aperire partus<br>Lenis, Ilithyia, tuere matres,<br>Sive tu Lucina probas vocari<br>Seu Genitalis:<br><br>Diva, producas subolem patrumque<br>Prosperes decreta super iugandis<br>Feminis prolisque novae feraci<br>Lege marita,<br><br>Certus undenos deciens per annos<br>Orbis ut cantus referatque ludos<br>Ter die claro totiensque grata<br>Nocte frequentes.<br><br>Vosque veraces cecinisse, Parcae,<br>Quod semel dictumst stabilisque rerum<br>Terminus servet, bona iam peractis<br>Iungite fata.<br><br>Fertilis frugum pecorisque tellus<br>Spicea donet Cererem corona;<br>Nutriant fetus et aquae salubres<br>Et Iovis aurae.<br><br>Condito mitis placidusque telo<br>Supplices audi pueros, Apollo;<br>Siderum regina bicornis, audi,<br>Luna, puellas:<br><br>Roma si vestrumst opus, Iliaeque<br>Litus Etruscum tenuere turmae,<br>Iussa pars mutare Lares et urbem<br>Sospite cursu,<br><br>Cui per ardentem sine fraude Troiam<br>Castus Aeneas patriae superstes<br>Liberum munivit iter, daturus<br>Plura relictis:<br><br>Di, probos mores docili iuventae,<br>Di, senectuti placidae quietem,<br>Romulae genti date remque prolemque<br>Et decus omne.<br><br>Quaeque vos bobus veneratur albis<br>Clarus Anchisae Venerisque sanguis,<br>Impetret, bellante prior, iacentem<br>Lenis in hostem.<br><br>iam mari terraque manus potentes<br>Medus Albanasque timet secures,<br>Iam Scythae responsa petunt superbi<br>Nuper, et Indi.<br><br>Iam Fides et Pax et Honor Pudorque<br>Priscus et neglecta redire Virtus<br>Audet, adparetque beata pleno<br>Copia cornu.<br><br>Augur et fulgente decorus arcu<br>Phoebus acceptusque novem Camenis,<br>Qui salutari levat arte fessos<br>Corporis artus,<br><br>Si Palatinas videt aequus arces,<br>Remque Romanam Latiumque felix<br>Alterum in lustrum meliusque semper<br>Prorogat aevum.<br><br>Quaeque Aventinum tenet Algidumque,<br>Quindecim Diana preces virorum<br>Curat et votis puerorum amicas<br>Adplicat aures.<br><br>Haec Iovem sentire deosque cunctos<br>Spem bonam certamque domum reporto,<br>Doctus et Phoebi chorus et Dianae<br>Dicere laudes.", "st": "CS"}], []);})();
